          B : T2_Access;
       end record;

       type T2 is record
          A : T1_Access;
       end record;

    end Mutually_Dependent;

Later on, we'll see that these code examples can be written using
:ref:`anonymous access types <Adv_Ada_Mutually_Dependent_Types_Using_Anonymous_Access_Types>`.

.. admonition:: In the Ada Reference Manual

    - :arm22:`3.10.1 Incomplete Type Declarations <3-10-1>`


.. _Adv_Ada_Null_Records:

Null records
------------

A null record is a record that doesn't have any components. Consequently, it
cannot store any information. When declaring a null record, we simply
write :ada:`null` instead of declaring actual components, as we usually do for
records. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Null_Record

    package Null_Recs is

       type Null_Record is record
          null;
       end record;

    end Null_Recs;

Note that the syntax can be simplified to :ada:`is null record`, which is much
more common than the previous form:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Null_Record

    package Null_Recs is

       type Null_Record is null record;

    end Null_Recs;

Although a null record doesn't have components, we can still specify
subprograms for it. For example, we could specify an addition operation for it:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Null_Record

    package Null_Recs is

       type Null_Record is null record;

       function "+" (A, B : Null_Record)
                     return Null_Record;

    end Null_Recs;

    package body Null_Recs is

       function "+" (A, B : Null_Record)
                     return Null_Record
       is
          pragma Unreferenced (A, B);
       begin
          return (null record);
       end "+";

    end Null_Recs;

    with Null_Recs; use Null_Recs;

    procedure Show_Null_Rec is
       A, B : Null_Record;
    begin
       B := A + A;
       A := A + B;
    end Show_Null_Rec;

.. admonition:: In the Ada Reference Manual

    - :arm22:`4.3.1 Record Aggregates <4-3-1>`

Simple Prototyping
~~~~~~~~~~~~~~~~~~

A null record doesn't provide much functionality on itself, as we're not
storing any information in it. However, it's far from being useless. For
example, we can make use of null records to design an API, which we can then
use in an application without having to implement the actual functionality of
the API. This allows us to design a prototype without having to think about all
the implementation details of the API in the first stage.

Consider this example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Device

    package Devices is

       type Device is private;

       function Create
         (Active : Boolean)
          return Device;

       procedure Reset
         (D : out Device) is null;

       procedure Process
         (D : in out Device) is null;

       procedure Activate
         (D : in out Device) is null;

       procedure Deactivate
         (D : in out Device) is null;

    private

       type Device is null record;

       function Create (Active : Boolean)
                        return Device is
         (null record);

    end Devices;

    with Ada.Text_IO; use Ada.Text_IO;
    with Devices;     use Devices;

    procedure Show_Device is
       A : Device;
    begin
       Put_Line ("Creating device...");
       A := Create (Active => True);

       Put_Line ("Processing on device...");
       Process (A);

       Put_Line ("Deactivating device...");
       Deactivate (A);

       Put_Line ("Activating device...");
       Activate (A);

       Put_Line ("Resetting device...");
       Reset (A);
    end Show_Device;

In the :ada:`Devices` package, we're declaring the :ada:`Device` type and its
primitive subprograms: :ada:`Create`, :ada:`Reset`, :ada:`Process`,
:ada:`Activate` and :ada:`Deactivate`. This is the API that we use in our
prototype. Note that, although the :ada:`Device` type is declared as a private
type, it's still defined as a null record in the full view.

In this example, the :ada:`Create` function, implemented as an expression
function in the private part, simply returns a null record. As expected, this
null record returned by :ada:`Create` matches the definition of the
:ada:`Device` type.

All procedures associated with the :ada:`Device` type are implemented as null
procedures, which means they don't actually have an implementation nor have any
effect. We'll discuss this topic
:ref:`later on in the course <Adv_Ada_Null_Procedures>`.

In the :ada:`Show_Device` procedure |mdash| which is an application
that implements our prototype |mdash|, we declare an object of :ada:`Device`
type and call all subprograms associated with that type.

Extending the prototype
~~~~~~~~~~~~~~~~~~~~~~~

Because we're either using expression functions or null procedures in the
specification of the :ada:`Devices` package, we don't have a package body for
it (as there's nothing to be implemented). We could, however, move those user
messages from the :ada:`Show_Devices` procedure to a dummy implementation of
the :ada:`Devices` package. This is the adapted code:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Device

    package Devices is

       type Device is null record;

       function Create (Active : Boolean)
                        return Device;

       procedure Reset (D : out Device);

       procedure Process (D : in out Device);

       procedure Activate (D : in out Device);

       procedure Deactivate (D : in out Device);

    end Devices;

    with Ada.Text_IO; use Ada.Text_IO;

    package body Devices is

       function Create (Active : Boolean)
                        return Device
       is
          pragma Unreferenced (Active);
       begin
          Put_Line ("Creating device...");
          return (null record);
       end Create;

       procedure Reset (D : out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Processing on device...");
       end Reset;

       procedure Process (D : in out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Deactivating device...");
       end Process;

       procedure Activate (D : in out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Activating device...");
       end Activate;

       procedure Deactivate (D : in out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Resetting device...");
       end Deactivate;

    end Devices;

    with Devices; use Devices;

    procedure Show_Device is
       A : Device;
    begin
       A := Create (Active => True);
       Process (A);
       Deactivate (A);
       Activate (A);
       Reset (A);
    end Show_Device;

As we changed the specification of the :ada:`Devices` package to not use null
procedures, we now need a corresponding package body for it. In this package
body, we  implement the operations on the :ada:`Device` type, which actually
just display a user message indicating which operation is being called.

Let's focus on this updated version of the :ada:`Show_Device` procedure. Now
that we've removed all those calls to :ada:`Put_Line` from this procedure and
just have the calls to operations associated with the :ada:`Device` type, it
becomes more apparent that, even though :ada:`Device` is just a null record, we
can design an application with a sequence of various commands operating on it.
Also, when we just read the source-code of the :ada:`Show_Device` procedure,
there's no clear indication that the :ada:`Device` type doesn't actually hold
any information.

More complex applications
~~~~~~~~~~~~~~~~~~~~~~~~~

As we've just seen, we can use null records like any other type and create
complex prototypes with them. We could, for instance, design an application
that makes use of many null records, or even have types that depend on or
derive from null records. Let's see a simple example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Derived_Device

    package Many_Devices is

       type Device is null record;

       type Device_Config is null record;

       function Create (Config : Device_Config)
                        return Device is
         (null record);

       type Derived_Device is new Device;

       procedure Process (D : Derived_Device) is null;

    end Many_Devices;

    with Many_Devices; use Many_Devices;

    procedure Show_Derived_Device is
       A : Device;
       B : Derived_Device;
       C : Device_Config;
    begin
       A := Create (Config => C);
       B := Create (Config => C);

       Process (B);
    end Show_Derived_Device;

In this example, the :ada:`Create` function has a null record parameter
(of :ada:`Device_Config` type) and returns a null record (of :ada:`Device`
type). Also, we derive the :ada:`Derived_Device` type from the :ada:`Device`
type. Consequently, :ada:`Derived_Device` is also a null record (since it's
derived from a null record). In the :ada:`Show_Derived_Device` procedure, we
declare objects of those types (:ada:`A`, :ada:`B` and :ada:`C`) and call
primitive subprograms to operate on them.

This example shows that, even though the types we've declared are *just* null
records, they can still be used to represent dependencies in our application.

Implementing the API
~~~~~~~~~~~~~~~~~~~~

Let's focus again on the previous example. After we have an initial prototype,
we can start implementing some of the functionality needed for the
:ada:`Device` type. For example, we can store information about the current
activation state in the record:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Null_Records.Device

    package Devices is

       type Device is private;

       function Create (Active : Boolean)
                        return Device;

       procedure Reset (D : out Device);

       procedure Process (D : in out Device);

       procedure Activate (D : in out Device);

       procedure Deactivate (D : in out Device);

    private

       type Device is record
          Active : Boolean;
       end record;

    end Devices;

    with Ada.Text_IO; use Ada.Text_IO;

    package body Devices is

       function Create (Active : Boolean)
                        return Device
       is
          pragma Unreferenced (Active);
       begin
          Put_Line ("Creating device...");
          return (Active => Active);
       end Create;

       procedure Reset (D : out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Processing on device...");
       end Reset;

       procedure Process (D : in out Device)
       is
          pragma Unreferenced (D);
       begin
          Put_Line ("Deactivating device...");
       end Process;

       procedure Activate (D : in out Device)
       is
       begin
          Put_Line ("Activating device...");
          D.Active := True;
       end Activate;

       procedure Deactivate (D : in out Device)
       is
       begin
          Put_Line ("Resetting device...");
          D.Active := False;
       end Deactivate;

    end Devices;

    with Ada.Text_IO; use Ada.Text_IO;
    with Devices;     use Devices;

    procedure Show_Device is
       A : Device;
    begin
       A := Create (Active => True);
       Process (A);
       Deactivate (A);
       Activate (A);
       Reset (A);
    end Show_Device;

Now, the :ada:`Device` record contains an :ada:`Active` component, which is
used in the updated versions of :ada:`Create`, :ada:`Activate` and
:ada:`Deactivate`.

    procedure Show_Object_Assignments is
       A1, A2 : T (5, 6);
       B      : T (7, 8);
    begin
       A1 := A2;    --  OK
       B  := A1;    --  ERROR!
    end Show_Object_Assignments;

In this example, the :ada:`A1 := A2` assignment is accepted because both
:ada:`A1` and :ada:`A2` have the same constraints (:ada:`(5, 6)`). However, the
:ada:`B := A1` assignment is not accepted because the discriminant check fails
at runtime.

Note that the discriminant check is not performed when we use
:ref:`mutable subtypes <Adv_Ada_Mutable_Subtypes>` |mdash| we discuss this
specific kind of subtypes later on.


Discriminant type
~~~~~~~~~~~~~~~~~

In a discriminant specification, the type of the discriminant can only be a
discrete subtype or an
:ref:`access type <Adv_Ada_Discriminants_As_Access_Values>`. Other kinds of
types |mdash| e.g. composite types such as record types |mdash| are illegal for
discriminants. However, we can always use them indirectly by using access
types. (We'll see an example later.)

In addition to that, we can also use a different kind of access types, namely
:ref:`anonymous access-to-object subtypes <Adv_Ada_Anonymous_Access_To_Object_Types>`.
This specific kind of discriminant is called
:ref:`access discriminant <Adv_Ada_Anonymous_Access_Discriminants>`. We discuss
this topic in more detail in another chapter.

Let's see a code example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Discriminants_Subtype

    package Recs is

       type Usage_Mode is (Off,
                           Simple_Usage,
                           Advanced_Usage);

       type Priv_Info is private;

       type Priv_Info_Access is access Priv_Info;

       type Proc_Access is
         access procedure (P : in out Priv_Info);

       type Priv_Rec (Last  : Positive;
                      Usage : Usage_Mode;
                      Info  : Priv_Info_Access;
                      Proc  : Proc_Access) is
         private;

    private

       type Priv_Info is record
         A : Positive;
         B : Positive;
       end record;

       type Priv_Rec (Last  : Positive;
                      Usage : Usage_Mode;
                      Info  : Priv_Info_Access;
                      Proc  : Proc_Access) is
         null record;

    end Recs;

In this example, we're declaring the :ada:`Priv_Rec` type with the following
discriminants:

- The :ada:`Last` discriminant of the scalar (i.e. discrete) type
  :ada:`Positive`;

- The :ada:`Usage` discriminant of the enumeration (i.e. discrete) type
  :ada:`Usage_Mode`;

- The :ada:`Info` discriminant of the
  :ref:`access-to-object type <Adv_Ada_Access_Types_Terminology>`
  :ada:`Priv_Info_Access`;

    - We discuss
      :ref:`access-to-object types as discriminant type <Adv_Ada_Discriminants_As_Access_Values>`
      in another chapter.

- The :ada:`Proc` discriminant of the
  :ref:`access-to-subprogram type <Adv_Ada_Access_To_Subprograms>`
  :ada:`Proc_Access`;

    - We discuss
      :ref:`access-to-subprogram types as discriminant type <Adv_Ada_Access_To_Subprograms_As_Discriminant_Type>`
      in another chapter.

As indicated previously, it's illegal to use a private type or a record type as
the type of a discriminant. For example:


.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Discriminants_Subtype_Error
    :class: ada-expect-compile-error

    package Recs is

       type Priv_Info is private;

       type Priv_Rec (Info : Priv_Info) is
         private;
       --             ^^^^^^^^^^^^^^^^
       --  ERROR: cannot use private type
       --         in discriminant.

    private

       type Priv_Info is record
         A : Positive;
         B : Positive;
       end record;

       type Priv_Rec (Info  : Priv_Info) is
         null record;

    end Recs;

We cannot use the :ada:`Priv_Info` directly as a discriminant type because it's
a private type. However, as we've just seen in the previous code example, we
use it indirectly by using an access type to this private type (see
:ada:`Priv_Info_Access` in the code example).


.. _Adv_Ada_Indefinite_Subtype_Discriminant:

Indefinite subtypes as discriminants
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

As we already implied, we cannot use indefinite subtypes as discriminants. For
example, the following code won't compile:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types_Error
    :class: ada-expect-compile-error

    package Unconstrained_Types is

       type Integer_Array is
         array (Positive range <>) of Integer;

       type Simple_Record (Arr : Integer_Array) is
       --                  ^^^^^^^^^^^^^^^^^^^
       --  ERROR: cannot use indefinite type
       --         in discriminant.
       record
          L : Natural := Arr'Length;
       end record;

    end Unconstrained_Types;

:ada:`Integer_Array` is a correct type declaration |mdash| although
the type itself is indefinite after the declaration. However, we cannot
use it as the discriminant in the declaration of :ada:`Simple_Record`.
We could, however, have a correct declaration by using discriminants as
access values:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types_Error

    package Unconstrained_Types is

       type Integer_Array is
         array (Positive range <>) of Integer;

       type Integer_Array_Access is
         access Integer_Array;

       type Simple_Record
         (Arr : Integer_Array_Access) is
       record
          L : Natural := Arr'Length;
       end record;

    end Unconstrained_Types;

By adding the :ada:`Integer_Array_Access` type and using it in
:ada:`Simple_Record`\'s type declaration, we can indirectly use an
indefinite type in the declaration of another indefinite type. We discuss
this topic later
:ref:`in another chapter <Adv_Ada_Discriminants_As_Access_Values>`.


.. _Adv_Ada_Record_Discriminants_Default_Values:

Default values
~~~~~~~~~~~~~~

We can specify default values for discriminants. Note, however, that we must
either specify default values for **all** discriminants of the discriminant
part or for none of them. This contrasts with default values for subprogram
parameters, where we can
:ref:`specify default values for just a subset of all parameters of a specific subprogram <Adv_Ada_Parameter_Order_And_Association>`.

As expected, we can override the default values by specifying the values of
each discriminant when declaring an object. Let's see a simple example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Discriminant_Default_Value

    package Recs is

       type T (L : Positive := 1;
               M : Positive := 2) is
         private;

    private

       type T (L : Positive := 1;
               M : Positive := 2) is
         null record;

    end Recs;

    with Ada.Text_IO; use Ada.Text_IO;

    with Recs;        use Recs;

    procedure Show_Object_Declaration is
       A : T;
       B : T (7, 8);
    begin
       Put_Line ("A.L = "
                 & A.L'Image);
       Put_Line ("A.M = "
                 & A.M'Image);
       Put_Line ("B.L = "
                 & B.L'Image);
       Put_Line ("B.M = "
                 & B.M'Image);
    end Show_Object_Declaration;

In this example, object :ada:`A` makes use of the default values for the
discriminants of type :ada:`T`, so it has the discriminants
:ada:`(L => 1, M => 2)`. In the case of object :ada:`B`, we're specifying the
values :ada:`(L => 7, M => 8)`, which are used instead of the default values.

Note that we cannot set default values for nonlimited tagged types. The same
applies to generic formal types. For example:

.. todo::

    Add link to section on generic formal types once it's available.

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Discriminant_Default_Value_Tagged_TYpe
    :class: ada-expect-compile-error

    package Recs is

       type TT (L : Positive := 1;
                M : Positive := 2) is
       --       ^^^^^^^^^^^^^^^^^
       --  ERROR: cannot assign default
       --         in discriminant of
       --         nonlimited tagged type.
         tagged private;

       type LTT (L : Positive := 1;
                 M : Positive := 2) is
         tagged limited private;

    private

       type TT (L : Positive := 1;
                M : Positive := 2) is
         tagged null record;

       type LTT (L : Positive := 1;
                 M : Positive := 2) is
         tagged limited null record;

    end Recs;

As we can see, compilation fails because of the default values for the
discriminants of the nonlimited tagged type :ada:`TT`. In the case of the
limited tagged type :ada:`LTT`, the default values for the discriminants are
legal.


.. _Adv_Ada_Mutable_Subtypes:

Mutable subtypes
^^^^^^^^^^^^^^^^

An unconstrained discriminated subtype with defaults is called a mutable
subtype, and a variable of such a subtype is called a mutable variable because
the discriminants of such a variable can be changed. An important feature of
mutable subtypes is that it allows for changing the discriminants of an object
via assignments |mdash| in this case, no
:ref:`discriminant check <Adv_Ada_Discriminant_Check>` is performed.

Let's see an example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Mutable_Subtype
    :class: ada-run-expect-failure

    package Mutability is

       type T_Non_Mutable
         (L : Positive;
          M : Positive) is
         null record;

       type T_Mutable
         (L : Positive := 1;
          M : Positive := 2) is
         null record;

    end Mutability;

    with Mutability; use Mutability;

    procedure Show_Mutable_Subtype_Assignment is
       NM_1 : T_Non_Mutable (5, 6);
       NM_2 : T_Non_Mutable (7, 8);

       M_1  : T_Mutable (7, 8);
       M_2  : T_Mutable;
    begin
       NM_2 := NM_1;  --  ERROR!
       M_2  := M_1;   --  OK
    end Show_Mutable_Subtype_Assignment;

In this example, the :ada:`NM_2 := NM_1` assignment fails because both objects
are of a non-mutable subtype with different discriminants, so that the
discriminant check fails at runtime. However, the :ada:`M_2 := M_1` assignment
is OK because both objects are mutable variables. In this case, this assignment
changes the discriminants of :ada:`M_2` from :ada:`(L => 1, M => 2)` to
:ada:`(L => 7, M => 8)`.

Note that assignments of mutable variables may not always work at runtime. For
example, if a discriminant of a mutable subtype is used to constrain a
component of indefinite subtype, we might see the corresponding checks fail at
runtime. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Mutable_Subtype_Error
    :class: ada-run-expect-failure

    package Mutability is

       type T_Mutable_Array (L : Positive := 10) is
         private;

    private

       type Integer_Array is
         array (Positive range <>) of Integer;

       type T_Mutable_Array (L : Positive := 10) is
       record
          Arr : Integer_Array (1 .. L);
       end record;

    end Mutability;

    with Ada.Text_IO; use Ada.Text_IO;

    with Mutability;  use Mutability;

    procedure Show_Mutable_Subtype_Error is
       A : T_Mutable_Array (10);
       B : T_Mutable_Array (20);
    begin
       Put_Line ("A'Size = "
                 & A'Size'Image);
       Put_Line ("B'Size = "
                 & B'Size'Image);

       A := B;  --  ERROR!
    end Show_Mutable_Subtype_Error;

In this case, the assignment :ada:`A := B` raises the :ada:`Constraint_Error`
exception at runtime. Here, the :ada:`Arr` component of each object has a
different range: :ada:`1 .. 10` for object :ada:`A` and :ada:`1 .. 20` for
object :ada:`B`.
To prevent this situation, we should declare :ada:`T_Mutable_Array` as a
limited type, so that assignments are not permitted.


Derived types and subtypes
~~~~~~~~~~~~~~~~~~~~~~~~~~

As expected, we may derive types with discriminants or declare subtypes of it.
However, there are a couple of details associated with this, which we discuss
now.

Subtypes
^^^^^^^^

When declaring a subtype of a type with discriminants, we have the choice to
specify the value of the discriminants for the parent type, or specify no
discriminants at all:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Subtypes

    package Subtypes_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       subtype Sub_T is T;
       --  Discriminants are not specified:
       --  taking the ones from T.

       subtype Sub_T_2 is T
        (L => 3, M => 4);
       --  Discriminants are specified:
       --  taking the ones from Sub_T_2

    end Subtypes_With_Discriminants;

For the :ada:`Sub_T` subtype declaration in this example, we don't specify
values for the parent type's discriminants. For :ada:`Sub_T_2`, in contrast, we
set the discriminants to :ada:`(L => 3, M => 4)`.

When declaring objects of these subtypes, we need to take the constraints into
account:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Subtypes
    :class: ada-run-expect-failure

    package Subtypes_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       subtype Sub_T is T;
       --  Discriminants are not specified:
       --  taking the ones from T.

       subtype Sub_T_2 is T
        (L => 3, M => 4);
       --  Discriminants are specified:
       --  taking the ones from Sub_T_2

    end Subtypes_With_Discriminants;

    with Subtypes_With_Discriminants;
    use  Subtypes_With_Discriminants;

    procedure Show_Subtypes_With_Discriminants is
       A1 : T (1, 2);
       A2 : T (3, 4);
       B1 : Sub_T (1, 2);
       B2 : Sub_T (3, 4);
       C2 : Sub_T_2;

       --  C1 : Sub_T_2 (1, 2);
       --                ^^^^
       --  ERROR: discriminants already
       --         constrained
    begin
       B1 := A1;
       --  OK: discriminants match

       B2 := A1;
       --  CONSTRAINT_ERROR!

       B2 := A2;
       --  OK: discriminants match

       C2 := A1;
       --  CONSTRAINT_ERROR!

       C2 := A2;
       --  OK: discriminants match
    end Show_Subtypes_With_Discriminants;

For objects of :ada:`Sub_T` subtype, we *have to* specify the value of each
discriminant. On the other hand, for objects of :ada:`Sub_T_2` type, we
*cannot* specify the constraints because they have already been defined in the
subtype's declaration |mdash| in this case, they're always set to
:ada:`(3, 4)`.

When assigning objects of different subtypes, the discriminant check will be
performed |mdash| as we
:ref:`mentioned before <Adv_Ada_Record_Discriminants_Object_Assignments>`. In
this example, the assignments :ada:`B2 := A1` and :ada:`C2 := A1` fail because
the objects have different constraints.


Derived types
^^^^^^^^^^^^^

The behavior for derived types is very similar to the one we've just described
for subtypes. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types

    package Derived_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       type T_Derived is new T;
       --  Discriminants are not specified:
       --  taking the ones from T.

       type T_Derived_2 is new T
         (L => 3, M => 4);
       --  Discriminants are specified:
       --  taking the ones from T_Derived_2

    end Derived_With_Discriminants;

For the :ada:`T_Derived` type, we reuse the discriminants of the parent type
:ada:`T`. For the :ada:`T_Derived_2` type, we specify a value for each
discriminant of :ada:`T`.

As you probably notice, this code looks very similar to the code using
subtypes. The main difference between using subtypes and derived types is that,
as expected, we have to perform a
:ref:`type conversion <Adv_Ada_Type_Conversion>` in the assignments:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types
    :class: ada-run-expect-failure

    with Derived_With_Discriminants;
    use  Derived_With_Discriminants;

    procedure Show_Derived_With_Discriminants is
       A1 : T (1, 2);
       A2 : T (3, 4);
       B1 : T_Derived (1, 2);
       B2 : T_Derived (3, 4);
       C2 : T_Derived_2;

       --  C1 : Sub_T_2 (1, 2);
       --                ^^^^
       --  ERROR: discriminants already
       --         constrained
    begin
       B1 := T_Derived (A1);
       --  OK: discriminants match

       B2 := T_Derived (A1);
       --  ERROR!

       C2 := T_Derived_2 (A1);
       --  CONSTRAINT_ERROR!

       C2 := T_Derived_2 (A2);
       --  OK: discriminants match
    end Show_Derived_With_Discriminants;

Once again, a discriminant check is performed when assigning objects to ensure
that the type discriminants match. In this code example, the assignments
:ada:`B2 := A1` and :ada:`C2 := A1` fail because the objects have different
constraints.


Derived types with renamed discriminants
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

We could rewrite a type declaration such as :ada:`type T_Derived is new T` by
explicitly declaring the discriminants. We can do that for the previous code
example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_Same_Discriminants

    package Derived_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       --  The declaration:
       --
       --     type T_Derived is new T;
       --
       --  is the same as:
       --
       type T_Derived
         (L : Positive;
          M : Positive) is
         new T (L => L, M => M);

    end Derived_With_Discriminants;

We may, however, rename the discriminants instead. For example, we could rename
:ada:`L` and :ada:`M` to :ada:`X` and :ada:`Y`. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_Renamed_Discriminants

    package Derived_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       type T_Derived
         (X : Positive;
          Y : Positive) is
         new T (L => X, M => Y);

    end Derived_With_Discriminants;

Of course, if we use named association when declaring objects, we have to use
the correct discriminant names:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_Renamed_Discriminants

    with Ada.Text_IO; use Ada.Text_IO;

    with Derived_With_Discriminants;
    use  Derived_With_Discriminants;

    procedure Show_Derived_With_Discriminants is
       A : T (L => 1, M => 2);
       B : T_Derived (X => 3, Y => 4);
       --             ^^^^^^^^^^^^^^
       --  Using correct discriminant names
    begin
       Put_Line ("A.L = "
                 & A.L'Image);
       Put_Line ("A.M = "
                 & A.M'Image);
       Put_Line ("B.X = "
                 & B.X'Image);
       Put_Line ("B.Y = "
                 & B.Y'Image);
    end Show_Derived_With_Discriminants;

In essence, the discriminants of both parent and derived types are the same:
the only difference is that they are accessed by different names. This allows
us to convert from a parent type to a derived type:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_Renamed_Discriminants

    with Derived_With_Discriminants;
    use  Derived_With_Discriminants;

    procedure Show_Derived_With_Discriminants is
       A : T (L => 1, M => 2);
       B : T_Derived (X => 1, Y => 2);
    begin
       B := T_Derived (A);  --  OK
    end Show_Derived_With_Discriminants;

Here, even though objects :ada:`A` and :ada:`B` have discriminants with
different names, the assignment :ada:`B := T_Derived (A)` is valid.


Derived types with more constrained discriminants
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

When deriving types with discriminants, we may use a more constrained type for
the discriminants of derived type. For example, if the discriminant :ada:`D` of
the parent type is of :ada:`Integer` type, the corresponding discriminant of
the derived type may use a constrained subtype such as :ada:`Natural` or
:ada:`Positive` |mdash| because both :ada:`Natural` and :ada:`Positive` are
subtypes of type :ada:`Integer`. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_More_Constrained_Discriminants

    package Derived_With_Discriminants is

       type T
         (L : Integer;
          M : Integer) is
         null record;

       type T_Derived_2
         (X : Natural;
          Y : Positive) is
         new T (L => X, M => Y);

    end Derived_With_Discriminants;

As expected, the constraints of each discriminant's type are taken into account
when evaluating the value that is specified for each discriminant:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_More_Constrained_Discriminants

    with Ada.Text_IO; use Ada.Text_IO;

    with Derived_With_Discriminants;
    use  Derived_With_Discriminants;

    procedure Show_Derived_With_Discriminants is
       A : T (L => -1, M => -2);
       B : T_Derived_2 (X => 0, Y => 1);
    begin
       Put_Line ("A.L = "
                 & A.L'Image);
       Put_Line ("A.M = "
                 & A.M'Image);
       Put_Line ("B.X = "
                 & B.X'Image);
       Put_Line ("B.Y = "
                 & B.Y'Image);
    end Show_Derived_With_Discriminants;

Here, we can use :ada:`(L => -1, M => -2)` in the declaration of object
:ada:`A` because both discriminants are of :ada:`Integer` type. However, in the
declaration of object :ada:`B`, we can only use values for the discriminants
that are in the range of the :ada:`Natural` and :ada:`Positive` subtypes,
respectively. (If you change the code to use negative values instead, a
:ada:`Constraint_Error` exception is raised at runtime.)


Extending the discriminant part
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

As we've seen, we can rename discriminants or use more constrained subtypes for
discriminants in derived types. We might also want to add a new discriminant to
the derived type |mdash| in addition to the discriminants of the parent's type.
However, this is considered a type extension, as the new discriminant is part
of the type definition.

As an example, we may want to add the :ada:`A` discriminant of :ada:`Boolean`
type to a derived type. For non-tagged types, such a declaration will trigger a
compilation error as expected:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Discriminants.Derived_Types_Extension_Error
    :class: ada-expect-compile-error

    package Derived_With_Discriminants is

       type T
         (L : Positive;
          M : Positive) is
         null record;

       type T_Derived
         (X : Positive;
          Y : Positive;
          A : Boolean) is
       --  ^^^^^^^^^^^
       --  ERROR: cannot extend type with new
       --         Boolean discriminant A
         new T (L => X, M => Y);

    end Derived_With_Discriminants;

To circumvent this issue, we could, of course, declare a component of :ada:`T`
type instead of deriving from it:

In the remaining parts of this section, we discuss a couple of details about
variant records.

.. admonition:: In the Ada Reference Manual

    - :arm:`3.8.1 Variant Parts and Discrete Choices <3-8-1>`


Discriminant type and value coverage
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

The subtype of discriminants used in the variant part must be of a discrete
type |mdash| it cannot be of an access or a floating-point type, for example.
Also, all possible values of the subtype of each discriminant must be covered
in the case statement of the variant part. For example, consider the following
variant record:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Coverage
    :class: ada-expect-compile-error

    package Subtype_Coverage is

       type Var_Rec (Value : Integer) is
       record
          case Value is
             when 0 .. 100 =>
                I : Integer;

             --  ERROR: missing values!
          end case;
       end record;

    end Subtype_Coverage;

This package cannot be compiled because, in the variant part, we're only
covering values for the :ada:`Value` discriminant in the range between 0 and
100. To fix this compilation error, we have to cover all values instead. For
example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Coverage

    package Subtype_Coverage is

       type Var_Rec (Value : Integer) is
       record
          case Value is
             when Integer'First .. -1 =>
                null;
             when 0 .. 100 =>
                I : Integer;
             when 101 .. Integer'Last =>
                null;
          end case;
       end record;

    end Subtype_Coverage;

Of course, specifying all possible values can be difficult. As an alternative,
we could simplify the case statement by just using :ada:`others` as a discrete
choice that encompasses all values that haven't been specified earlier in the
case statement:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Coverage

    package Subtype_Coverage is

       type Var_Rec (Value : Integer) is
       record
          case Value is
             when 0 .. 100 =>
                I : Integer;
             when others =>
                null;
          end case;
       end record;

    end Subtype_Coverage;

By using :ada:`when others => ...` in this last example, we ensure that all
values have been covered.


Record size
~~~~~~~~~~~

When declaring an object, the values we select for the discriminants related to
the variant part have an impact on the overall size of that object |mdash| in
fact, it may be smaller or bigger depending on this selection. Let's see an
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Size

    package Variant_Records is

       type Simple_Record
         (Extended : Boolean := False) is
       record
          V : Integer;
          case Extended is
             when False =>
                null;
             when True  =>
                V_Float : Float;
          end case;
       end record;

    end Variant_Records;

    with Ada.Text_IO;     use Ada.Text_IO;

    with Variant_Records; use Variant_Records;

    procedure Show_Variant_Rec_Size is
       SR_No_Ext : Simple_Record
                     (Extended => False);
       SR_Ext    : Simple_Record
                     (Extended => True);
       SR        : Simple_Record;
    begin
       Put_Line ("SR_No_Ext'Size : "
                 & SR_No_Ext'Size'Image
                 & " bits");
       Put_Line ("SR_Ext'Size : "
                 & SR_Ext'Size'Image
                 & " bits");
       Put_Line ("SR'Size : "
                 & SR'Size'Image
                 & " bits");
    end Show_Variant_Rec_Size;

As we can confirm when we run this application, the choice for the discriminant
has an impact on the size of the object. In the case of the :ada:`SR_No_Ext`
object, setting the :ada:`Extended` discriminant to :ada:`False` excludes the
:ada:`V_Float` component. For the :ada:`SR_Ext` object, on the other hand, we
include the :ada:`V_Float` component. Therefore, on a typical PC, the size of
:ada:`SR_No_Ext` is 8 bytes (4 bytes for the :ada:`Extended` discriminant and
4 bytes for the :ada:`V` component), while the size of :ada:`SR_Ext` is 12
bytes (i.e., additional 4 bytes for the :ada:`V_Float` component).

In the case of :ada:`SR`, because the object isn't constrained, the size of the
object is 12 bytes on a typical PC |mdash| the same size as :ada:`SR_Ext`. This
is because :ada:`SR` has to account for the case when all components must be
available, even though the :ada:`Extended` discriminant is set to :ada:`False`
by default. Remember that an assignment such as :ada:`SR := SR_Ext` is valid,
so enough memory must be available to ensure that the assignment is performed
correctly.

This principle applies to more complicated variant records. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Size

    package Variant_Records is

       type Simple_Record
         (Extended   : Boolean := False;
          Extended_2 : Boolean := False) is
       record
          V : Integer;
          case Extended is
             when False =>
                case Extended_2 is
                   when False =>
                      null;
                   when True  =>
                      V_Int_2 : Integer;
                      V_Int_3 : Integer;
                end case;
             when True  =>
                V_Float : Float;
                case Extended_2 is
                   when False =>
                      null;
                   when True  =>
                      V_Float_2 : Float;
                end case;
          end case;
       end record;

    end Variant_Records;

    with Ada.Text_IO;     use Ada.Text_IO;

    with Variant_Records; use Variant_Records;

    procedure Show_Variant_Rec_Size is
       SR : Simple_Record;
    begin
       Put_Line ("SR'Size : "
                 & SR'Size'Image
                 & " bits");
    end Show_Variant_Rec_Size;

In this example, the size of :ada:`SR` is 16 bytes on a typical PC. This
accounts for 4 bytes for the discriminants :ada:`Extended` and
:ada:`Extended_2`, and 4 bytes for each of the 3 components that are being
taken into account for the worst case:

- components :ada:`V`, :ada:`V_Int_2` and :ada:`V_Int_3` when we set
  :ada:`Extended => False, Extended_2 => True`;

- components :ada:`V`, :ada:`V_Float` and :ada:`V_Float_2` when we set
  :ada:`Extended => True, Extended_2 => True`.

Note that a memory block is shared between the :ada:`V_Int_2` and
:ada:`V_Int_3` components from the first worst case, and :ada:`V_Float` and the
:ada:`V_Float_2` components from the second worst case. As we can see, the
compiler will typically optimize the size of a record as much as possible by
assessing which components are really needed for the worst case.

Also, as we discussed previously, we can use
:ref:`unchecked unions <Adv_Ada_Unchecked_Union>` in combination with variant
records, which has an impact on the object size.


Ensuring valid information
~~~~~~~~~~~~~~~~~~~~~~~~~~

We can use variant parts to prevent invalid information from being used. Let's
look again at the :ada:`Device` type from the previous code example:

.. code-block:: ada

       type Device (State : Device_State) is
       record
          case State is
             when Off =>
                null;
             when On =>
                Info : Device_Info;
          end case;
       end record;

For the sake of this example, we could say that a device that is turned off
doesn't have any valuable information. Therefore, the device information stored
in the :ada:`Info` component of the :ada:`Device` type is only valid if the
device is turned on. Thus, if the device is turned off (i.e.,
:ada:`Device_State = Off`), we should prevent the application from processing
device information that is probably incorrect. Let's extend the previous code
example to accommodate this requirement:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Device

    package Devices is

       type Device_State is
         (Off, On);

       type Device
         (State : Device_State := Off) is
           private;

       procedure Turn_Off (D : in out Device);

       procedure Turn_On (D : in out Device);

       type Device_Info is
       record
          V : Float;
       end record;

       function Current_Info (D : Device)
                              return Device_Info;

    private

       type Device (State : Device_State := Off) is
       record
          case State is
             when Off =>
                null;
             when On =>
                Info : Device_Info;
          end case;
       end record;

       Device_Off : constant Device :=
                      (State => Off);

       Device_On  : constant Device :=
                      (State => On,
                       others => <>);

    end Devices;

    package body Devices is

       procedure Turn_Off (D : in out Device) is
       begin
          D := Device_Off;
       end Turn_Off;

       procedure Turn_On (D : in out Device) is
       begin
          D := Device_On;
       end Turn_On;

       function Current_Info (D : Device)
                              return Device_Info is
         (D.Info);

    end Devices;

Let's create a test application called :ada:`Show_Device` that makes use of
this device by turning it on and off, and by retrieving information from it:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Device
    :class: ada-run-expect-failure

    with Devices; use Devices;

    procedure Show_Device is
       D : Device;
       I : Device_Info;
    begin
       Turn_On (D);
       I := Current_Info (D);

       Turn_Off (D);

       --  The following call raises
       --  an exception at runtime
       --  because D is turned off.
       I := Current_Info (D);
    end Show_Device;

In this example, by using the variant part, we're preventing information
retrieved by an inappropriate call to the :ada:`Current_Info` function from being used
elsewhere in the application. In fact, if the device is turned off, a call to
:ada:`Current_Info` raises the :ada:`Constraint_Error` exception because the
:ada:`Info` component isn't accessible. We see that effect in the
:ada:`Show_Device` procedure: the call to :ada:`Current_Info` *fails* (by raising
an exception) when the device has just been turned off.

To avoid exceptions at runtime, we must check the device's state before
calling :ada:`Current_Info`:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Device

    with Devices; use Devices;

    procedure Show_Device is
       D : Device;
       I : Device_Info;
    begin
       Turn_On (D);

       if D.State = On then
          I := Current_Info (D);
       end if;

       Turn_Off (D);

       if D.State = On then
          I := Current_Info (D);
       end if;
    end Show_Device;

Now, no exception is raised, as we only retrieve information from
the device when it is turned on |mdash| that is, we only call the
:ada:`Current_Info` function when the :ada:`State` discriminant of the object is
set to :ada:`On`.


Extending record types
~~~~~~~~~~~~~~~~~~~~~~

We can use variant parts as a means to extend record types. This can be viewed
as a static approach to implement type extension |mdash| similar to type
extension via tagged types, but with clear differences.

Let's say we have a sensor, and we implement a package called :ada:`Sensors`
that interfaces with that sensor:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Records.Variant_Parts.Sensors

    package Sensors is

       type Sensor is private;

However, you might want to use Unicode symbols in your Ada source code to
declare constants |mdash| as we did in the previous sections |mdash| and store
the source code in a UTF-8 coded file. In this case, you need to be careful about
how this file is parsed by the compiler.

Let's look at this source-code example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_Strings

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    procedure Show_UTF_8_Strings is

        Symbols_UTF_8 : constant
          UTF_8_String := "♥♫";

    begin
        Put_Line ("UTF_8_String: "
                  & Symbols_UTF_8);

        Put_Line ("Length:       "
                  & Symbols_UTF_8'Length'Image);

    end Show_UTF_8_Strings;

Here, we're using Unicode symbols to initialize the :ada:`Symbols_UTF_8`
constant of :ada:`UTF_8_String` type.

Now, let's assume this source-code example is stored in a UTF-8 coded file.
Because the :ada:`"♥♫"` string makes use of non-ASCII Unicode symbols,
representing this string in UTF-8 format will require more than 2 bytes.
In fact, each one of those Unicode symbols requires 2 bytes to be encoded in
UTF-8. (Keep in mind that Unicode symbols may require
:wikipedia:`between 1 to 4 bytes <UTF-8>` to be encoded in UTF-8 format.) Also,
in this case, the UTF-8 encoding process is using two additional bytes.
Therefore, the total length of the string is six, which matches what we see
when running the :ada:`Show_UTF_8_Strings` procedure. In other words, the
length of the :ada:`Symbols_UTF_8` string doesn't refer to those two characters
(:ada:`"♥♫"`) that we were using in the constant declaration, but the length of
the encoded bytes in its UTF-8 representation.

The UTF-8 format is very useful for storing and transmitting texts. However, if
we want to process Unicode symbols, it's probably better to use string types
with 32-bit characters |mdash| such as :ada:`Wide_Wide_String`. For example,
let's say we want to use the :ada:`"♥♫"` string again to initialize a constant
of :ada:`Wide_Wide_String` type:

.. code:: ada no_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.WWS_Strings_W8 switches=Compiler(-gnatW8);

    with Ada.Text_IO;
    with Ada.Wide_Wide_Text_IO;

    procedure Show_WWS_Strings is

       package TIO   renames Ada.Text_IO;
       package WWTIO renames Ada.Wide_Wide_Text_IO;

       Symbols_WWS : constant
         Wide_Wide_String := "♥♫";

    begin
       WWTIO.Put_Line ("Wide_Wide_String: "
                       & Symbols_WWS);

       TIO.Put_Line ("Length:           "
                     & Symbols_WWS'Length'Image);

    end Show_WWS_Strings;

In this case, as mentioned above, if we store this source code in a text file
using UTF-8 format, we need to ensure that the UTF-8 coded symbols are
correctly interpreted by the compiler when it parses the text file.
Otherwise, we might get unexpected behavior. (Interpreting the characters in
UTF-8 format as Latin-1 format is certainly an example of what we want to avoid
here.)

.. _Adv_Ada_GNAT_W8_Switch:

.. admonition:: In the GNAT toolchain

    You can use UTF-8 coding in your source-code file and initialize strings of
    32-bit characters. However, as we just mentioned, you need to make sure
    that the UTF-8 coded symbols are correctly interpreted by the compiler when
    dealing with types such as :ada:`Wide_Wide_String`. For this case, GNAT
    offers the ``-gnatW8`` switch. Let's run the previous example using this
    switch:

    .. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.WWS_Strings_W8 switches=Compiler(-gnatW8);

        with Ada.Text_IO;
        with Ada.Wide_Wide_Text_IO;

        procedure Show_WWS_Strings is

           package TIO   renames Ada.Text_IO;
           package WWTIO renames Ada.Wide_Wide_Text_IO;

           Symbols_WWS : constant
             Wide_Wide_String := "♥♫";

        begin
           WWTIO.Put_Line ("Wide_Wide_String: "
                           & Symbols_WWS);

           TIO.Put_Line ("Length:           "
                         & Symbols_WWS'Length'Image);

        end Show_WWS_Strings;

    Because the :ada:`Wide_Wide_String` type has 32-bit characters. we expect
    the length of the string to match the number of symbols that we're using.
    Indeed, when running the :ada:`Show_WWS_Strings` procedure, we see that
    the :ada:`Symbols_WWS` string has a length of two characters, which matches
    the number of characters of the :ada:`"♥♫"` string.

    When we use the ``-gnatW8`` switch, GNAT converts the UTF-8-coded string
    (:ada:`"♥♫"`) to UTF-32 format, so we get two 32-bit characters. It then
    uses the UTF-32-coded string to initialize the :ada:`Symbols_WWS` string.

    If we don't use the ``-gnatW8`` switch, however, we get wrong results.
    Let's look at the same example again without the switch:

    .. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.WWS_Strings_No_W8

        with Ada.Text_IO;
        with Ada.Wide_Wide_Text_IO;

        procedure Show_WWS_Strings is

           package TIO   renames Ada.Text_IO;
           package WWTIO renames Ada.Wide_Wide_Text_IO;

           Symbols_WWS : constant
             Wide_Wide_String := "♥♫";

        begin
           WWTIO.Put_Line ("Wide_Wide_String: "
                           & Symbols_WWS);

           TIO.Put_Line ("Length:           "
                         & Symbols_WWS'Length'Image);

        end Show_WWS_Strings;

    Now, the :ada:`"♥♫"` string is being interpreted as a string of six 8-bit
    characters. (In other words, the UTF-8-coded string isn't converted to
    the UTF-32 format.) Each of those 8-bit characters is then stored in a
    32-bit character of the :ada:`Wide_Wide_String` type. This explains why
    the :ada:`Show_WWS_Strings` procedure reports a length of 6 components for
    the :ada:`Symbols_WWS` string.

Portability of UTF-8 in source-code files
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

In a previous code example, we were assuming that the format that we use for
the source-code file is UTF-8. This allows us to simply use Unicode symbols
directly in strings:

.. code-block:: ada

    Symbol_UTF_8 : constant UTF_8_String := "★";

This approach, however, might not be portable. For example, if the compiler
uses a different string encoding for source-code files, it might interpret that
Unicode character as something else |mdash| or just throw a compilation error.

If you're afraid that format mismatches might happen in your compilation
environment, you may want to write strings in your code in a completely
portable fashion, which consists in entering the exact sequence of codes in
bytes |mdash| using the :ada:`Character'Val` function |mdash| for the symbols
you want to use.

We can reuse parts of the previous example and replace the UTF-8 character with
the corresponding UTF-8 code:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    procedure Show_UTF_8 is

       Symbol_UTF_8 : constant
         UTF_8_String :=
           Character'Val (16#e2#)
           & Character'Val (16#98#)
           & Character'Val (16#85#);

    begin
       Put_Line ("UTF-8 String: "
                 & Symbol_UTF_8);
    end Show_UTF_8;

Here, we use a sequence of three calls to the :ada:`Character'Val(code)`
function for the UTF-8 code that corresponds to the "★" symbol.


.. _Adv_Ada_UTF_8_Files_Wide_Wide_Strings:

Parsing UTF-8 files for Wide-Wide-String processing
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

A typical use-case is to parse a text file in UTF-8 format and use *wide-wide*
strings to process the lines of that file. Before we look at the implementation
that does that, let's first write a procedure that generates a text file in
UTF-8 format:

.. code:: ada no_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_File_Processing

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    procedure Generate_UTF_8_File
      (Output_File_Name : String)
    is
       F : File_Type;
    begin
       Create (F, Out_File, Output_File_Name);
       Put_Line (F, UTF_8_String'("♥♫"));
       Put_Line
         (F,
          UTF_8_String'("مرحبا يا عالم"));
       Close (F);
    end Generate_UTF_8_File;

Procedure :ada:`Generate_UTF_8_File` writes two strings with non-Latin
characters into the UTF-8 file indicated by the :ada:`Output_File_Name`
parameter.

In addition, let's implement an auxiliary procedure to display the individual
characters of a *wide-wide* string:

.. code:: ada no_button project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_File_Processing

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    with Ada.Strings.UTF_Encoding.Wide_Wide_Strings;
    use  Ada.Strings.UTF_Encoding.Wide_Wide_Strings;

    procedure Put_Line_UTF_8_Characters
      (WSS : Wide_Wide_String)
    is
       procedure Put_Complete_UTF_8_String
         (WSS : Wide_Wide_String)
       is
          S_UTF_8 : constant UTF_8_String :=
                      Encode (WSS);
       begin
          Put_Line ("STRING: " & S_UTF_8);
          Put_Line ("Length: "
                    & WSS'Length'Image
                    & " characters");
          New_Line;
       end Put_Complete_UTF_8_String;

       --  This is a wrapper function of the
       --  Encode function for the
       --  Wide_Wide_Character type:
       function Encode (Item : Wide_Wide_Character)
                        return UTF_8_String
        is
           SC : constant Wide_Wide_String (1 .. 1)
                  := (1 => Item);
           --  We need a 1-character string
           --  for the call to Encode.
       begin
           return Encode (SC);
       end Encode;

       procedure Put_UTF_8_Characters
         (WSS : Wide_Wide_String) is
       begin
          for I in WSS'Range loop
             Put (I'Image & ": ");
             Put (Encode (WSS (I)));
             New_Line;
          end loop;
       end Put_UTF_8_Characters;

    begin
        Put_Complete_UTF_8_String (WSS);
        Put_UTF_8_Characters (WSS);
        Put_Line ("--------------------");
    end Put_Line_UTF_8_Characters;

Finally, let's look at a code example that parses an UTF-8 file:

.. code:: ada run_button main=show_utf_8.adb project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_File_Processing

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    with Ada.Strings.UTF_Encoding.Wide_Wide_Strings;
    use  Ada.Strings.UTF_Encoding.Wide_Wide_Strings;

    with Generate_UTF_8_File;
    with Put_Line_UTF_8_Characters;

    procedure Show_UTF_8 is

       File_Name : constant String :=
                     "utf-8_test.txt";

       procedure Read_UTF_8_File
         (Input_File_Name : String)
       is
          F : File_Type;
       begin
          Open (F, In_File, Input_File_Name);

          while not End_Of_File (F) loop
             declare
                S_UTF8 : constant UTF_8_String
                           := Get_Line (F);
                S      : constant Wide_Wide_String
                           := Decode (S_UTF8);
             begin
                Put_Line_UTF_8_Characters (S);
             end;
          end loop;
          Close (F);
       end Read_UTF_8_File;

    begin
       Generate_UTF_8_File (File_Name);
       Read_UTF_8_File (File_Name);
    end Show_UTF_8;

The :ada:`Show_UTF_8` procedure first calls the :ada:`Generate_UTF_8_File`
procedure to generate a text file in UTF-8 format, and then calls the nested
:ada:`Read_UTF_8_File` procedure to read from that file |mdash| this is done by
reading the 8-bit UTF-8 encoded string and decoding it into a string of
:ada:`Wide_Wide_String` type.

(Note that we call the auxiliary :ada:`Put_Line_UTF_8_Characters` procedure to
display the characters of each line we read from the UTF-8 file.)

For completeness, we include the nested :ada:`Read_Write_UTF_8_File` procedure,
which not only reads each line from a UTF-8 file, but also writes it into
another UTF-8 file:

.. code:: ada run_button main=show_utf_8.adb project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_File_Processing

    with Ada.Text_IO; use Ada.Text_IO;

    with Ada.Strings.UTF_Encoding;
    use  Ada.Strings.UTF_Encoding;

    with Ada.Strings.UTF_Encoding.Wide_Wide_Strings;
    use  Ada.Strings.UTF_Encoding.Wide_Wide_Strings;

    with Generate_UTF_8_File;
    with Put_Line_UTF_8_Characters;

    procedure Show_UTF_8 is

       File_Name_In  : constant String :=
                         "utf-8_test.txt";
       File_Name_Out : constant String :=
                         "utf-8_copy.txt";

       procedure Read_Write_UTF_8_File
         (Input_File_Name,
         Output_File_Name : String)
       is
          F_In, F_Out : File_Type;
       begin
          Open (F_In, In_File, Input_File_Name);
          Create (F_Out, Out_File, Output_File_Name);

          while not End_Of_File (F_In) loop
             declare
                S : constant Wide_Wide_String :=
                      Decode (Get_Line (F_In));
             begin
                Put_Line_UTF_8_Characters (S);
                Put_Line (F_Out, Encode (S));
             end;
          end loop;

          Close (F_In);
          Close (F_Out);
       end Read_Write_UTF_8_File;

    begin
       Generate_UTF_8_File (File_Name_In);

       Read_Write_UTF_8_File
         (Input_File_Name  => File_Name_In,
          Output_File_Name => File_Name_Out);
    end Show_UTF_8;

In the nested :ada:`Read_Write_UTF_8_File` procedure, we see both :ada:`Decode`
and :ada:`Encode` functions being called to convert from and to the
:ada:`UTF_8_String` type, respectively.

.. admonition:: In the GNAT toolchain

    If we use the ``-gnatW8`` switch, which we mentioned
    :ref:`in a previous section <Adv_Ada_GNAT_W8_Switch>`, the implementation
    of :ada:`Generate_UTF_8_File` and :ada:`Put_Line_UTF_8_Characters` must be
    adapted. In addition, we can simplify the implementation of the
    :ada:`Show_UTF_8` procedure, too. (Note, however, that the previous
    implementation, which makes use of the :ada:`Decode` and :ada:`Encode`
    functions, would work fine as well.)

    .. code:: ada run_button main=show_utf_8.adb project=Courses.Advanced_Ada.Data_Types.Strings.String_Encoding.UTF_8_File_Processing switches=Compiler(-gnatW8);

        with Ada.Wide_Wide_Text_IO;
        use  Ada.Wide_Wide_Text_IO;

        procedure Put_Line_UTF_8_Characters
          (WSS : Wide_Wide_String)
        is
           procedure Put_Complete_UTF_8_String
             (WSS : Wide_Wide_String)
           is
           begin
              Put_Line ("STRING: " & WSS);
              Put_Line ("Length: "
                        & WSS'Length'Wide_Wide_Image
                        & " characters");
              New_Line;
           end Put_Complete_UTF_8_String;

           procedure Put_UTF_8_Characters
             (WSS : Wide_Wide_String)
           is
           begin
              for I in WSS'Range loop
                 Put (I'Wide_Wide_Image & ": ");
                 Put (WSS (I));
                 New_Line;
              end loop;
           end Put_UTF_8_Characters;

        begin
            Put_Complete_UTF_8_String (WSS);
            Put_UTF_8_Characters (WSS);
            Put_Line ("--------------------");
        end Put_Line_UTF_8_Characters;

        with Ada.Wide_Wide_Text_IO;
        use  Ada.Wide_Wide_Text_IO;

        procedure Generate_UTF_8_File
          (Output_File_Name : String)
        is
           F : File_Type;
        begin
           Create (F, Out_File, Output_File_Name);
           Put_Line (F, "♥♫");
           Put_Line (F, "مرحبا يا عالم");
           Close (F);
        end Generate_UTF_8_File;

        with Ada.Wide_Wide_Text_IO;
        use  Ada.Wide_Wide_Text_IO;

        with Generate_UTF_8_File;
        with Put_Line_UTF_8_Characters;

        procedure Show_UTF_8 is

           File_Name_In  : constant String :=
                             "utf-8_test.txt";
           File_Name_Out : constant String :=
                             "utf-8_copy.txt";

           procedure Read_Write_UTF_8_File
             (Input_File_Name,
              Output_File_Name : String)
           is
              F_In, F_Out : File_Type;
           begin
              Open (F_In, In_File, Input_File_Name);
              Create (F_Out, Out_File, Output_File_Name);

              while not End_Of_File (F_In) loop
                 declare
                    S : constant Wide_Wide_String :=
                          Get_Line (F_In);
                 begin
                    Put_Line_UTF_8_Characters (S);
                    Put_Line (F_Out, S);
                 end;
              end loop;

              Close (F_In);
              Close (F_Out);
           end Read_Write_UTF_8_File;

        begin
           Generate_UTF_8_File (File_Name_In);

           Read_Write_UTF_8_File
             (Input_File_Name  => File_Name_In,
              Output_File_Name => File_Name_Out);
        end Show_UTF_8;

    In this version of the code, we've removed all references to the
    :ada:`UTF_8_String` type |mdash| as well as the :ada:`Decode` and
    :ada:`Encode` functions that we were using to convert from and to this
    type. In this case, all UTF-8 processing happens directly using strings of
    :ada:`Wide_Wide_Strings` type.


.. _Adv_Ada_Image_Attribute:

Image attribute
---------------

Overview
~~~~~~~~

In the :ref:`Introduction to Ada <Intro_Ada_Image_Attribute>` course, we've
seen that the :ada:`Image` attribute returns a string that contains a textual
representation of an object. For example, we write :ada:`Integer'Image (V)` to
get a string for the integer variable :ada:`V`:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Simple_Image

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Simple_Image is
       V : Integer;
    begin
       V := 10;
       Put_Line ("V: " & Integer'Image (V));
    end Show_Simple_Image;

Naturally, we can use the :ada:`Image` attribute with other scalar types. For
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Simple_Image

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Simple_Image is
       type Status is (Unknown, Off, On);

       V : Float;
       S : Status;
    begin
       V := 10.0;
       S := Unknown;

       Put_Line ("V: " & Float'Image (V));
       Put_Line ("S: " & Status'Image (S));
    end Show_Simple_Image;

In this example, we retrieve a string representing the floating-point
variable :ada:`V`. Also, we use :ada:`Status'Image (V)` to retrieve a string representing the textual version of the :ada:`Status`.

.. admonition:: In the Ada Reference Manual

    - :arm22:`Image Attributes <4-10>`


:ada:`Type'Image` and :ada:`Obj'Image`
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

We can also apply the :ada:`Image` attribute to an object directly:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Simple_Image

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Simple_Image is
       V : Integer;
    begin
       V := 10;
       Put_Line ("V: " & V'Image);

       --  Equivalent to:
       --  Put_Line ("V: " & Integer'Image (V));
    end Show_Simple_Image;

In this example, the :ada:`Integer'Image (V)` and :ada:`V'Image` forms are
equivalent.


.. _Adv_Ada_Wider_Versions_Image_Attribute:

Wider versions of :ada:`Image`
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

Although we've been talking only about the :ada:`Image` attribute, it's
important to mention that each of the wider versions of the string types also
has a corresponding :ada:`Image` attribute. In fact, this is the attribute for
each string type:

+------------------------+----------------------------+
| Attribute              | Type of Returned String    |
+========================+============================+
| :ada:`Image`           | :ada:`String`              |
+------------------------+----------------------------+
| :ada:`Wide_Image`      | :ada:`Wide_String`         |
+------------------------+----------------------------+
| :ada:`Wide_Wide_Image` | :ada:`Wide_Wide_String`    |
+------------------------+----------------------------+

Let's see a simple example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Wide_Wide_Image

    with Ada.Wide_Wide_Text_IO;
    use  Ada.Wide_Wide_Text_IO;

    procedure Show_Wide_Wide_Image is
       F : Float;
    begin
       F := 100.0;
       Put_Line ("F = "
                 & F'Wide_Wide_Image);
    end Show_Wide_Wide_Image;

In this example, we use the :ada:`Wide_Wide_Image` attribute to retrieve a
string of :ada:`Wide_Wide_String` type for the floating-point variable
:ada:`F`.


:ada:`Image` attribute for non-scalar types
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

.. note::

   This feature was introduced in Ada 2022.

In the previous code examples, we were using the :ada:`Image` attribute with
scalar types, but it isn't restricted to those types. In fact, we can also use
this attribute when dealing with non-scalar types. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Non_Scalar_Image switches=Compiler(-gnat2022);

    package Simple_Records is

       type Rec is limited private;

       type Rec_Access is access Rec;

       function Init return Rec;

       type Null_Rec is null record;

    private

       type Rec is limited record
          F : Float;
          I : Integer;
       end record;

       function Init return Rec is
          ((F => 10.0, I => 4));

    end Simple_Records;

    with Ada.Text_IO; use Ada.Text_IO;
    with Ada.Unchecked_Deallocation;

    with Simple_Records;
    use  Simple_Records;

    procedure Show_Non_Scalar_Image is

       procedure Free is
         new Ada.Unchecked_Deallocation
           (Object => Rec,
            Name   => Rec_Access);

       R_A : Rec_Access :=
         new Rec'(Init);

       N_R : Null_Rec :=
         (null record);
    begin
       R_A := new Rec'(Init);
       N_R := (null record);

       Put_Line ("R_A:     " & R_A'Image);
       Put_Line ("R_A.all: " & R_A.all'Image);
       Put_Line ("N_R:     " & N_R'Image);

       Free (R_A);
       Put_Line ("R_A:     " & R_A'Image);
    end Show_Non_Scalar_Image;

In the :ada:`Show_Non_Scalar_Image` procedure from this example, we display the
access value of :ada:`R_A` and the contents of the dereferenced access object
(:ada:`R_A.all`). Also, we see the indication that :ada:`N_R` is a null record
and :ada:`R_A` is null after the call to :ada:`Free`.

.. admonition:: Historically

    Since Ada 2022, the :ada:`Image` attribute is available for all types.
    Prior to this version of the language, it was only available for scalar
    types. (For other kind of types, programmers had to use the :ada:`Image`
    attribute for each component of a record, for example.)

    In fact, prior to Ada 2022, the :ada:`Image` attribute was described in
    the :arm22:`3.5 Scalar Types <3-5>` section of the Ada Reference Manual, as
    it was only applied to those types. Now, it is part of the new
    :arm22:`Image Attributes <4-10>` section.

Let's see another example, this time with arrays:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Array_Image switches=Compiler(-gnat2022);

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Array_Image is

       type Float_Array is
         array (Positive range <>) of Float;

       FA_3C   : Float_Array (1 .. 3);
       FA_Null : Float_Array (1 .. 0);

    begin
       FA_3C   := [1.0, 3.0, 2.0];
       FA_Null := [];

       Put_Line ("FA_3C:   " & FA_3C'Image);
       Put_Line ("FA_Null: " & FA_Null'Image);
    end Show_Array_Image;

In this example, we display the values of the three components of the
:ada:`FA_3C` array. Also, we display the null array :ada:`FA_Null`.


:ada:`Image` attribute for tagged types
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

In addition to untagged types, we can also use the :ada:`Image` attribute with
tagged types. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Tagged_Image switches=Compiler(-gnat2022);

    package Simple_Records is

       type Rec is tagged limited private;

       function Init return Rec;

       type Rec_Child is new Rec with private;

       overriding function Init return Rec_Child;

    private

       type Status is (Unknown, Off, On);

       type Rec is tagged limited record
          F : Float;
          I : Integer;
       end record;

       function Init return Rec is
          ((F => 10.0, I => 4));

       type Rec_Child is new Rec with record
          Z : Status;
       end record;

       function Init return Rec_Child is
          (Rec'(Init) with Z => Off);

    end Simple_Records;

    with Ada.Text_IO;    use Ada.Text_IO;

    with Simple_Records; use Simple_Records;

    procedure Show_Tagged_Image is
       R       : constant Rec       := Init;
       R_Class : constant Rec'Class := Rec'(Init);
       R_C     : constant Rec_Child := Init;
    begin
       Put_Line ("R:       " & R'Image);
       Put_Line ("R_Class: " & R_Class'Image);
       Put_Line ("R_A:     " & R_C'Image);
    end Show_Tagged_Image;

In the :ada:`Show_Tagged_Image` procedure from this example, we display the
contents of the :ada:`R` object of :ada:`Rec` type and the :ada:`R_Class`
object of :ada:`Rec'Class` type. Also, we display the contents of the
:ada:`R_C` object of the :ada:`Rec_Child` type, which is derived from the
:ada:`Rec` type.


:ada:`Image` attribute for task and protected types
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

We can also apply the :ada:`Image` attribute to protected objects and tasks:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Image_Attribute.Protected_Task_Image switches=Compiler(-gnat2022);

    package Simple_Tasking is

       protected type Protected_Float (I : Integer) is

       private
          V : Float := Float (I);
       end Protected_Float;

       protected type Protected_Null is
       private
       end Protected_Null;

       task type T is
          entry Start;
       end T;

    end Simple_Tasking;

    package body Simple_Tasking is

       protected body Protected_Float is

       end Protected_Float;

       protected body Protected_Null is

       end Protected_Null;

       task body T is
       begin
          accept Start;
       end T;

    end Simple_Tasking;

    with Ada.Text_IO;    use Ada.Text_IO;

    with Simple_Tasking; use Simple_Tasking;

    procedure Show_Protected_Task_Image is

       PF : Protected_Float (0);
       PN : Protected_Null;
       T1 : T;

    begin
       Put_Line ("PF: " & PF'Image);
       Put_Line ("PN: " & PN'Image);
       Put_Line ("T1: " & T1'Image);

       T1.Start;
    end Show_Protected_Task_Image;

In this example, we display information about the protected object :ada:`PF`,
the componentless protected object :ada:`PN` and the task :ada:`T1`.


.. _Adv_Ada_Put_Image_Aspect:

:ada:`Put_Image` aspect
-----------------------

.. note::

   This feature was introduced in Ada 2022.

Overview
~~~~~~~~

In the previous section, we discussed many details about the :ada:`Image`
attribute. In the code examples from that section, we've seen the default
behavior of this attribute: the string returned by the calls to :ada:`Image`
was always in the format defined by the Ada standard.

In some situations, however, we might want to customize the string that is
returned by the :ada:`Image` attribute of a type :ada:`T`. Ada allows us to do
that via the :ada:`Put_Image` aspect. This is what we have to do:

1. Specify the :ada:`Put_Image` aspect for the type :ada:`T` and indicate a
   procedure with a specific parameter profile |mdash| let's say, for example,
   a procedure named :ada:`P`.

2. Implement the procedure :ada:`P` and write the information we want to use
   into a buffer (by calling the routines defined for :ada:`Root_Buffer_Type`,
   such as the :ada:`Put` procedure).

We can see these steps performed in the code example below:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Strings.Put_Image.Simple_Put_Image switches=Compiler(-gnat2022);

    with Ada.Strings.Text_Buffers;

    package Show_Put_Image is

       type T is null record
         with Put_Image => Put_Image_T;
       --     ^ Custom version of Put_Image

       use Ada.Strings.Text_Buffers;

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T);

    end Show_Put_Image;

    package body Show_Put_Image is

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T) is
          pragma Unreferenced (Arg);
       begin
          --  Call Put with customized
          --  information
          Buffer.Put ("<custom info>");
       end Put_Image_T;

    end Show_Put_Image;

In the :ada:`Show_Put_Image` package, we use the :ada:`Put_Image` aspect in
the declaration of the :ada:`T` type. There, we indicate that the
:ada:`Image` attribute shall use the :ada:`Put_Image_T` procedure instead
of the default version.

In the body of the :ada:`Put_Image_T` procedure, we implement our custom
version of the :ada:`Image` attribute. We do that by calling the
:ada:`Put` procedure with the information we want to provide in the
:ada:`Image` attribute. Here, we access a buffer of :ada:`Root_Buffer_Type`
type, which is defined in the :ada:`Ada.Strings.Text_Buffers` package. (We
discuss more about this package
:ref:`later on <Adv_Ada_Universal_Text_Buffer>`.)

.. admonition:: In the Ada Reference Manual

    - :arm22:`Image Attributes <4-10>`


Complete Example of :ada:`Put_Image`
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

Let's see a complete example in which we use the :ada:`Put_Image` aspect and
write useful information to the buffer:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Put_Image.Put_Image_Custom_Numerics switches=Compiler(-gnat2022);

    with Ada.Strings.Text_Buffers;

    package Custom_Numerics is

       type Float_Integer is record
         F : Float   := 0.0;
         I : Integer := 0;
       end record
         with Dynamic_Predicate =>
                Integer (Float_Integer.F) =
                  Float_Integer.I,
              Put_Image         => Put_Float_Integer;
       --     ^ Custom version of Put_Image

       use Ada.Strings.Text_Buffers;

       procedure Put_Float_Integer
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        Float_Integer);

    end Custom_Numerics;

    package body Custom_Numerics is

       procedure Put_Float_Integer
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        Float_Integer) is
       begin
          --  Call Wide_Wide_Put with customized
          --  information
          Buffer.Wide_Wide_Put
            ("(F : "  & Arg.F'Wide_Wide_Image & ", "
             & "I : " & Arg.I'Wide_Wide_Image & ")");
       end Put_Float_Integer;

    end Custom_Numerics;

    with Ada.Text_IO;     use Ada.Text_IO;

    with Custom_Numerics; use Custom_Numerics;

    procedure Show_Put_Image is
       V : Float_Integer;
    begin
       V := (F => 100.2,
             I => 100);
       Put_Line ("V = "
                 & V'Image);
    end Show_Put_Image;

In the :ada:`Custom_Numerics` package of this example, we specify the
:ada:`Put_Image` aspect and indicate the :ada:`Put_Float_Integer` procedure.
In that procedure, we display the information of components :ada:`F` and
:ada:`I`. Then, in the :ada:`Show_Put_Image` procedure, we use the :ada:`Image`
attribute for the :ada:`V` variable and see the information in the exact format
we specified. (If you like to see the default version of the
:ada:`Put_Image` instead, you may comment out the :ada:`Put_Image` aspect part
in the declaration of :ada:`Float_Integer`.)


Relation to the :ada:`Image` attribute
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

Note that we cannot override the :ada:`Image` attribute directly |mdash|
there's no :ada:`Image` *aspect* that we could specify. However, as we've just
seen, we can do this indirectly by using our own version of the
:ada:`Put_Image` procedure for a type :ada:`T`.

The :ada:`Image` attribute of a type :ada:`T` makes use of the procedure
indicated in the :ada:`Put_Image` aspect. Let's say we have the following
declaration:

.. code-block:: ada

    type T is null record
      with Put_Image => Put_Image_T;

When we then use the :ada:`T'Image` attribute in our code, the custom
:ada:`Put_Image_T` procedure is automatically called. This is a simplified
example of how the :ada:`Image` function is implemented:

.. code-block:: ada

   function Image (V : T)
                   return String is
      Buffer : Custom_Buffer;
      --       ^ of Root_Buffer_Type'Class
   begin
      --  Calling Put_Image procedure
      --  for type T
      Put_Image_T (Buffer, V);

      --  Retrieving the text from the
      --  buffer as a string
      return Buffer.Get;
   end Image;

In other words, the :ada:`Image` attribute basically:

- calls the :ada:`Put_Image` procedure specified in the :ada:`Put_Image`
  aspect of type :ada:`T`\ 's declaration and passes a buffer;

and

- retrieves the contents of the buffer as a string and returns it.

If the :ada:`Put_Image` aspect of type :ada:`T` isn't specified, the default
version is used. (We've seen the default version of various types
:ref:`in the previous section <Adv_Ada_Image_Attribute>` about the :ada:`Image`
attribute.)


:ada:`Put_Image` and derived types
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

Types that were derived from untagged types (or null extensions) make use of
the :ada:`Put_Image` procedure that was specified for
their parent type |mdash| either a custom procedure indicated in the
:ada:`Put_Image` aspect or the default one. Naturally, if a derived type
has the :ada:`Put_Image` aspect, the procedure indicated in the aspect is used
instead. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Put_Image.Untagged_Put_Image switches=Compiler(-gnat2022);

    with Ada.Strings.Text_Buffers;

    package Untagged_Put_Image is

       use Ada.Strings.Text_Buffers;

       type T is null record
         with Put_Image => Put_Image_T;

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T);

       type T_Derived_1 is new T;

       type T_Derived_2 is new T
         with Put_Image => Put_Image_T_Derived_2;

       procedure Put_Image_T_Derived_2
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T_Derived_2);

    end Untagged_Put_Image;

    package body Untagged_Put_Image is

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T) is
          pragma Unreferenced (Arg);
       begin
          Buffer.Wide_Wide_Put ("Put_Image_T");
       end Put_Image_T;

       procedure Put_Image_T_Derived_2
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T_Derived_2) is
          pragma Unreferenced (Arg);
       begin
          Buffer.Wide_Wide_Put
            ("Put_Image_T_Derived_2");
       end Put_Image_T_Derived_2;

    end Untagged_Put_Image;

    with Ada.Text_IO;        use Ada.Text_IO;

    with Untagged_Put_Image; use Untagged_Put_Image;

    procedure Show_Untagged_Put_Image is
       Obj_T           : T;
       Obj_T_Derived_1 : T_Derived_1;
       Obj_T_Derived_2 : T_Derived_2;
    begin
       Put_Line ("T'Image :           "
                 & Obj_T'Image);
       Put_Line ("T_Derived_1'Image : "
                 & Obj_T_Derived_1'Image);
       Put_Line ("T_Derived_2'Image : "
                 & Obj_T_Derived_2'Image);
    end Show_Untagged_Put_Image;

In this example, we declare the type :ada:`T` and its derived types
:ada:`T_Derived_1` and :ada:`T_Derived_2`. When running this code, we see that:

- :ada:`T_Derived_1` makes use of the :ada:`Put_Image_T` procedure from its
  parent.

    - Note that, if we remove the :ada:`Put_Image` aspect from the declaration
      of :ada:`T`, the default version of the :ada:`Put_Image` procedure is
      used for both :ada:`T` and :ada:`T_Derived_1` types.

- :ada:`T_Derived_2` makes use of the :ada:`Put_Image_T_Derived_2` procedure,
  which was indicated in the :ada:`Put_Image` aspect of that type, instead of
  its parent's procedure.


:ada:`Put_Image` and tagged types
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

Types that are derived from a tagged type may also inherit the :ada:`Put_Image`
aspect. However, there are a couple of small differences in comparison to
untagged types, as we can see in the following example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Put_Image.Tagged_Put_Image switches=Compiler(-gnat2022);

    with Ada.Strings.Text_Buffers;

    package Tagged_Put_Image is

       use Ada.Strings.Text_Buffers;

       type T is tagged record
          I : Integer := 0;
       end record
         with Put_Image => Put_Image_T;

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T);

       type T_Child_1 is new T with record
          I1 : Integer;
       end record;

       type T_Child_2 is new T with null record;

       type T_Child_3 is new T with record
          I3 : Integer := 0;
       end record
         with Put_Image => Put_Image_T_Child_3;

       procedure Put_Image_T_Child_3
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T_Child_3);

    end Tagged_Put_Image;

    package body Tagged_Put_Image is

       procedure Put_Image_T
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T) is
          pragma Unreferenced (Arg);
       begin
          Buffer.Wide_Wide_Put ("Put_Image_T");
       end Put_Image_T;

       procedure Put_Image_T_Child_3
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        T_Child_3) is
          pragma Unreferenced (Arg);
       begin
          Buffer.Wide_Wide_Put
            ("Put_Image_T_Child_3");
       end Put_Image_T_Child_3;

    end Tagged_Put_Image;

    with Ada.Text_IO;      use Ada.Text_IO;

    with Tagged_Put_Image; use Tagged_Put_Image;

    procedure Show_Tagged_Put_Image is
       Obj_T         : T;
       Obj_T_Child_1 : T_Child_1;
       Obj_T_Child_2 : T_Child_2;
       Obj_T_Child_3 : T_Child_3;
    begin
       Put_Line ("T'Image :         "
                 & Obj_T'Image);
       Put_Line ("--------------------");
       Put_Line ("T_Child_1'Image : "
                 & Obj_T_Child_1'Image);
       Put_Line ("--------------------");
       Put_Line ("T_Child_2'Image : "
                 & Obj_T_Child_2'Image);
       Put_Line ("--------------------");
       Put_Line ("T_Child_3'Image : "
                 & Obj_T_Child_3'Image);
       Put_Line ("--------------------");
       Put_Line ("T'Class'Image :   "
                 & T'Class (Obj_T_Child_1)'Image);
    end Show_Tagged_Put_Image;

In this example, we declare the type :ada:`T` and its derived types
:ada:`T_Child_1`, :ada:`T_Child_2` and :ada:`T_Child_3`. When running this
code, we see that:

- for both :ada:`T_Child_1` and :ada:`T_Child_2`, the parent's
  :ada:`Put_Image` aspect (the :ada:`Put_Image_T` procedure) is called and its
  information is combined with the information from the type extension;

    - For the :ada:`T_Child_1` type, the :ada:`I1` component of the type
      extension is displayed by calling a default version of the
      :ada:`Put_Image` procedure for that component |mdash|
      ``(Put_Image_T with I1 =>  0)`` is displayed.

    - For the :ada:`T_Child_2` type, no additional information is displayed
      because this type has a null extension.

- for the :ada:`T_Child_3` type, the :ada:`Put_Image_T_Child_3` procedure,
  which was indicated in the :ada:`Put_Image` aspect of the type, is used.

Finally, class-wide types (such as :ada:`T'Class`) include additional
information. Here, the tag of the specific derived type is displayed first
|mdash| in this case, the tag of the :ada:`T_Child_1` type |mdash| and
then the actual information for the derived type is displayed.


.. _Adv_Ada_Universal_Text_Buffer:

Universal text buffer
---------------------

In the :ref:`previous section <Adv_Ada_Put_Image_Aspect>`, we've seen that the
first parameter of the procedure indicated in the :ada:`Put_Image` aspect has
the :ada:`Root_Buffer_Type'Class` type, which is defined in the
:ada:`Ada.Strings.Text_Buffers` package. In this section, we talk more about
this type and additional procedures associated with this type.

.. note::

   This feature was introduced in Ada 2022.

Overview
~~~~~~~~

We use the :ada:`Root_Buffer_Type'Class` type to implement a universal text
buffer that is used to store and retrieve information about data types. Because
this text buffer isn't associated with specific data types, it is universal
|mdash| in the sense that we can really use it for any data type, regardless of
the characteristics of this type.

In theory, we could use Ada's universal text buffer to implement applications
that actually process text in some form |mdash| for example, when implementing
a text editor. However, in general, Ada programmers are only expected to make
use of the :ada:`Root_Buffer_Type'Class` type when implementing a procedure for
the :ada:`Put_Image` aspect. For this reason, we won't discuss any kind of
type derivation |mdash| or any other kind of usages of this type |mdash| in
this section. Instead, we'll just focus on additional subprograms from the
:ada:`Ada.Strings.Text_Buffers` package.

.. admonition:: In the Ada Reference Manual

    - :arm22:`Universal Text Buffers <A-4-12>`


Additional procedures
~~~~~~~~~~~~~~~~~~~~~

In the previous section, we used the :ada:`Put` procedure |mdash| and the
related :ada:`Wide_Put` and :ada:`Wide_Wide_Put` procedures |mdash| from the
:ada:`Ada.Strings.Text_Buffers` package. In addition to these procedures, the
package also includes:

- the :ada:`New_Line` procedure, which writes a new line marker to the text
  buffer;

- the :ada:`Increase_Indent` procedure, which increases the indentation in the
  text buffer; and

- the :ada:`Decrease_Indent` procedure, which decreases the indentation in the
  text buffer.

The :ada:`Ada.Strings.Text_Buffers` package also includes the
:ada:`Current_Indent` function, which retrieves the current indentation
counter.

Let's revisit an example from the previous section and use the procedures
mentioned above:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Strings.Universal_Text_Buffer.Put_Image_Custom_Numerics switches=Compiler(-gnat2022);

    with Ada.Strings.Text_Buffers;

    package Custom_Numerics is

       type Float_Integer is record
         F : Float;
         I : Integer;
       end record
         with Dynamic_Predicate =>
                Integer (Float_Integer.F) =
                  Float_Integer.I,
              Put_Image         => Put_Float_Integer;
       --     ^ Custom version of Put_Image

       use Ada.Strings.Text_Buffers;

       procedure Put_Float_Integer
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        Float_Integer);

    end Custom_Numerics;

    package body Custom_Numerics is

       procedure Put_Float_Integer
         (Buffer : in out Root_Buffer_Type'Class;
          Arg    :        Float_Integer) is
       begin
          Buffer.Wide_Wide_Put ("(");
          Buffer.New_Line;

          Buffer.Increase_Indent;

          Buffer.Wide_Wide_Put
            ("F : "
             & Arg.F'Wide_Wide_Image);
          Buffer.New_Line;

          Buffer.Wide_Wide_Put
            ("I : "
            & Arg.I'Wide_Wide_Image);

          Buffer.Decrease_Indent;
          Buffer.New_Line;

          Buffer.Wide_Wide_Put (")");
       end Put_Float_Integer;

    end Custom_Numerics;

    with Ada.Text_IO;     use Ada.Text_IO;

    with Custom_Numerics; use Custom_Numerics;

    procedure Show_Put_Image is
       V : Float_Integer;
    begin
       V := (F => 100.2,
             I => 100);
       Put_Line ("V = "
                 & V'Image);
    end Show_Put_Image;

In the body of the :ada:`Put_Float_Integer` procedure, we're using the
:ada:`New_Line`, :ada:`Increase_Indent` and :ada:`Decrease_Indent` procedures
to improve the format of the string returned by the :ada:`Float_Integer'Image`
attribute. Using these procedures, you can create any kind of output format
for your custom type.

As the output of the program indicates, the smallest value (see
:ada:`Decimal'Small` in the example) is used to calculate the previous and next
values of :ada:`Decimal` type.

In the case of the :ada:`My_Float` type, the difference between the current
and the previous or next values is 1.40130E-45 (or 2\ :sup:`-149`) on a
standard PC.

Scalar To String Conversion
~~~~~~~~~~~~~~~~~~~~~~~~~~~

We've seen that we can use the :ada:`Image` and :ada:`Value` attributes to
perform conversions between values of a given subtype and a string:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Scalar_Types.Image_Value_Attr

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Image_Value_Attr is
       I : constant Integer := Integer'Value ("42");
    begin
       Put_Line (I'Image);
    end Show_Image_Value_Attr;

The :ada:`Image` and :ada:`Value` attributes are used for the :ada:`String`
type specifically. In addition to them, there are also attributes for different
string types |mdash| namely :ada:`Wide_String` and :ada:`Wide_Wide_String`.
This is the complete list of available attributes:

+-----------------------+-------------------------+---------------------------+
| Conversion type       | Attribute               | String type               |
+=======================+=========================+===========================+
| Conversion to string  | :ada:`Image`            | :ada:`String`             |
+                       +-------------------------+---------------------------+
|                       | :ada:`Wide_Image`       | :ada:`Wide_String`        |
+                       +-------------------------+---------------------------+
|                       | :ada:`Wide_Wide_Image`  | :ada:`Wide_Wide_String`   |
+-----------------------+-------------------------+---------------------------+
| Conversion to subtype | :ada:`Value`            | :ada:`String`             |
+                       +-------------------------+---------------------------+
|                       | :ada:`Wide_Value`       | :ada:`Wide_String`        |
+                       +-------------------------+---------------------------+
|                       | :ada:`Wide_Wide_Value`  | :ada:`Wide_Wide_String`   |
+-----------------------+-------------------------+---------------------------+

We discuss more about :ada:`Wide_String` and :ada:`Wide_Wide_String` in
:ref:`another section <Adv_Ada_Wide_Wide_Strings>`.

Width attribute
~~~~~~~~~~~~~~~

When converting a value to a string by using the :ada:`Image` attribute, we get
a string with variable width. We can assess the maximum width of that string
for a specific subtype by using the :ada:`Width` attribute. For example,
:ada:`Integer'Width` gives us the maximum width returned by the :ada:`Image`
attribute when converting a value of :ada:`Integer` type to a string of
:ada:`String` type.

This attribute is useful when we're using bounded strings in our code to store
the string returned by the :ada:`Image` attribute. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Scalar_Types.Width_Attr

    with Ada.Text_IO;         use Ada.Text_IO;
    with Ada.Strings;         use Ada.Strings;
    with Ada.Strings.Bounded;

    procedure Show_Width_Attr is
       package B_Str is new
         Ada.Strings.Bounded.Generic_Bounded_Length
           (Max => Integer'Width);
       use B_Str;

       Str_I : Bounded_String;

       I : constant Integer := 42;
       J : constant Integer := 103;
    begin
       Str_I := To_Bounded_String (I'Image);
       Put_Line ("Value:         "
                 & To_String (Str_I));
       Put_Line ("String Length: "
                 & Length (Str_I)'Image);
       Put_Line ("----");

       Str_I := To_Bounded_String (J'Image);
       Put_Line ("Value:         "
                 & To_String (Str_I));
       Put_Line ("String Length: "
                 & Length (Str_I)'Image);
    end Show_Width_Attr;

In this example, we're storing the string returned by :ada:`Image` in the
:ada:`Str_I` variable of :ada:`Bounded_String` type.

Similar to the :ada:`Image` and :ada:`Value` attributes, the :ada:`Width`
attribute is also available for string types other than :ada:`String`. In fact,
we can use:

- the :ada:`Wide_Width` attribute for strings returned by :ada:`Wide_Image`;
  and

- the :ada:`Wide_Wide_Width` attribute for strings returned by
  :ada:`Wide_Wide_Image`.

Other attributes
~~~~~~~~~~~~~~~~

The :ada:`Base` attribute is specific for numeric types. We discuss this topic
:ref:`in another chapter <Adv_Ada_Base_Attribute>`.


Enumerations
------------

We've introduced enumerations back in the
:ref:`Introduction to Ada course <Intro_Ada_Enum_Types>`.
In this section, we'll discuss a few useful features of enumerations, such as
enumeration renaming, enumeration overloading and representation clauses.

.. admonition:: In the Ada Reference Manual

    - :arm22:`3.5.1 Enumeration Types <3-5-1>`

Enumerations as functions
~~~~~~~~~~~~~~~~~~~~~~~~~

If you have used a programming language such as C in the past, you're familiar
with the concept of enumerations being constants with integer values. In Ada,
however, enumerations are not integers. In fact, they're actually parameterless
functions! Let's consider this example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_As_Function

    package Days is

       type Day is (Mon, Tue, Wed,
                    Thu, Fri,
                    Sat, Sun);

       --  Essentially, we're declaring
       --  these functions:
       --
       --  function Mon return Day;
       --  function Tue return Day;
       --  function Wed return Day;
       --  function Thu return Day;
       --  function Fri return Day;
       --  function Sat return Day;
       --  function Sun return Day;

    end Days;

In the package :ada:`Days`, we're declaring the enumeration type :ada:`Day`.
When we do this, we're essentially declaring seven parameterless functions, one
for each enumeration. For example, the :ada:`Mon` enumeration corresponds to
:ada:`function Mon return Day`. You can see all seven function declarations in
the comments of the example above.

Note that this has no direct relation to how an Ada compiler generates machine
code for enumeration. Even though enumerations are parameterless functions, a
typical Ada compiler doesn't generate function calls for code that deals with
enumerations.

Enumeration renaming
^^^^^^^^^^^^^^^^^^^^

The idea that enumerations are parameterless functions can be used when we want
to rename enumerations. For example, we could rename the enumerations of the
:ada:`Day` type like this:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_Renaming

    package Enumeration_Example is

       type Day is (Mon, Tue, Wed,
                    Thu, Fri,
                    Sat, Sun);

       function Monday    return Day renames Mon;
       function Tuesday   return Day renames Tue;
       function Wednesday return Day renames Wed;
       function Thursday  return Day renames Thu;
       function Friday    return Day renames Fri;
       function Saturday  return Day renames Sat;
       function Sunday    return Day renames Sun;

    end Enumeration_Example;

Now, we can use both :ada:`Monday` or :ada:`Mon` to refer to Monday of the
:ada:`Day` type:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_Renaming

    with Ada.Text_IO;         use Ada.Text_IO;
    with Enumeration_Example; use Enumeration_Example;

    procedure Show_Renaming is
       D1 : constant Day := Mon;
       D2 : constant Day := Monday;
    begin
       if D1 = D2 then
          Put_Line ("D1 = D2");
          Put_Line (Day'Image (D1)
                    & " =  "
                    & Day'Image (D2));
       end if;
    end Show_Renaming;

When running this application, we can confirm that :ada:`D1` is equal to
:ada:`D2`. Also, even though we've assigned :ada:`Monday` to :ada:`D2` (instead
of :ada:`Mon`), the application displays ``Mon = Mon``, since :ada:`Monday`
is just another name to refer to the actual enumeration (:ada:`Mon`).

.. admonition:: Hint

    If you just want to have a single (renamed) enumeration visible in your
    application |mdash| and make the original enumeration invisible |mdash|,
    you can use a separate package. For example:

    .. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_Renaming

        package Enumeration_Example is

           type Day is (Mon, Tue, Wed,
                        Thu, Fri,
                        Sat, Sun);

        end Enumeration_Example;

        with Enumeration_Example;

        package Enumeration_Renaming is

           subtype Day is Enumeration_Example.Day;

           function Monday    return Day renames
             Enumeration_Example.Mon;
           function Tuesday   return Day renames
             Enumeration_Example.Tue;
           function Wednesday return Day renames
             Enumeration_Example.Wed;
           function Thursday  return Day renames
             Enumeration_Example.Thu;
           function Friday    return Day renames
             Enumeration_Example.Fri;
           function Saturday  return Day renames
             Enumeration_Example.Sat;
           function Sunday    return Day renames
             Enumeration_Example.Sun;

        end Enumeration_Renaming;

        with Ada.Text_IO; use Ada.Text_IO;

        with Enumeration_Renaming;
        use  Enumeration_Renaming;

        procedure Show_Renaming is
           D1 : constant Day := Monday;
        begin
           Put_Line (Day'Image (D1));
        end Show_Renaming;

    Note that the call to :ada:`Put_Line` still displays ``Mon`` instead of
    ``Monday``.

Enumeration overloading
~~~~~~~~~~~~~~~~~~~~~~~

Enumerations can be overloaded. In simple terms, this means that the same name
can be used to declare an enumeration of different types. A typical example is
the declaration of colors:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_Overloading

    package Colors is

       type Color is
         (Salmon,
          Firebrick,
          Red,
          Darkred,
          Lime,
          Forestgreen,
          Green,
          Darkgreen,
          Blue,
          Mediumblue,
          Darkblue);

       type Primary_Color is
         (Red,
          Green,
          Blue);

    end Colors;

Note that we have :ada:`Red` as an enumeration of type :ada:`Color` and of type
:ada:`Primary_Color`. The same applies to :ada:`Green` and :ada:`Blue`. Because
Ada is a strongly-typed language, in most cases, the enumeration that we're
referring to is clear from the context. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Enumerations.Enumeration_Overloading

    with Ada.Text_IO; use Ada.Text_IO;
    with Colors;      use Colors;

    procedure Red_Colors is
       C1 : constant Color         := Red;
       --  Using Red from Color

       C2 : constant Primary_Color := Red;
       --  Using Red from Primary_Color
    begin
       if C1 = Red then
          Put_Line ("C1 = Red");
       end if;
       if C2 = Red then
          Put_Line ("C2 = Red");
       end if;
    end Red_Colors;

When assigning :ada:`Red` to :ada:`C1` and :ada:`C2`, it is clear that, in the
first case, we're referring to :ada:`Red` of :ada:`Color` type, while in the
second case, we're referring to :ada:`Red` of the :ada:`Primary_Color` type.
The same logic applies to comparisons such as the one in
:ada:`if C1 = Red`: because the type of :ada:`C1` is defined
(:ada:`Color`), it's clear that the :ada:`Red` enumeration is the one of
:ada:`Color` type.

Enumeration subtypes
^^^^^^^^^^^^^^^^^^^^

       type Integer_Array is
         array (Positive range <>) of Integer;

       type Simple_Record (Extended : Boolean) is
       record
          V : Integer;
          case Extended is
             when False =>
                null;
             when True  =>
                V_Float : Float;
          end case;
       end record;

    end Unconstrained_Types;

In this example, both :ada:`Integer_Array` and :ada:`Simple_Record` are
indefinite types.

As we've just mentioned, we cannot declare variables of indefinite types:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types
    :class: ada-expect-compile-error

    with Unconstrained_Types; use Unconstrained_Types;

    procedure Using_Unconstrained_Type is

       A : Integer_Array;

       R : Simple_Record;

    begin
       null;
    end Using_Unconstrained_Type;

As we can see when we try to build this example, the compiler complains about
the declaration of :ada:`A` and :ada:`R` because we're trying to use indefinite
types to declare variables. The main reason we cannot use indefinite types here
is that the compiler needs to know at this point how much memory it should
allocate. Therefore, we need to provide the information that is missing. In
other words, we need to change the declaration so the type becomes definite. We
can do this by either declaring a definite type or providing constraints in the
variable declaration. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types

    with Unconstrained_Types; use Unconstrained_Types;

    procedure Using_Unconstrained_Type is

       subtype Integer_Array_5 is
         Integer_Array (1 .. 5);

       A1 : Integer_Array_5;
       A2 : Integer_Array (1 .. 5);

       subtype Simple_Record_Ext is
         Simple_Record (Extended => True);

       R1 : Simple_Record_Ext;
       R2 : Simple_Record (Extended => True);

    begin
       null;
    end Using_Unconstrained_Type;

In this example, we declare the :ada:`Integer_Array_5` subtype, which is
definite because we're constraining it to a range from 1 to 5, thereby
defining the information that was missing in the indefinite type
:ada:`Integer_Array`. Because we now have a definite type, we can use it to
declare the :ada:`A1` variable. Similarly, we can use the indefinite type
:ada:`Integer_Array` directly in the declaration of :ada:`A2` by specifying the
previously unknown range.

Similarly, in this example, we declare the :ada:`Simple_Record_Ext` subtype,
which is definite because we're initializing the record discriminant
:ada:`Extended`. We can therefore use it in the declaration of the :ada:`R1`
variable. Alternatively, we can simply use the indefinite type
:ada:`Simple_Record` and specify the information required for the
discriminants. This is what we do in the declaration of the :ada:`R2` variable.

Although we cannot use indefinite types directly in variable declarations,
they're very useful to generalize algorithms. For example, we can use them as
parameters of a subprogram:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types

    with Unconstrained_Types; use Unconstrained_Types;

    procedure Show_Integer_Array (A : Integer_Array);

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Integer_Array (A : Integer_Array)
    is
    begin
       for I in A'Range loop
          Put_Line (Positive'Image (I)
                    & ": "
                    & Integer'Image (A (I)));
       end loop;
       Put_Line ("--------");
    end Show_Integer_Array;

    with Unconstrained_Types; use Unconstrained_Types;
    with Show_Integer_Array;

    procedure Using_Unconstrained_Type is
       A_5  : constant Integer_Array (1 .. 5)  :=
                (1, 2, 3, 4, 5);
       A_10 : constant Integer_Array (1 .. 10) :=
                (1, 2, 3, 4, 5, others => 99);
    begin
       Show_Integer_Array (A_5);
       Show_Integer_Array (A_10);
    end Using_Unconstrained_Type;

In this particular example, the compiler doesn't know a priori which range is
used for the :ada:`A` parameter of :ada:`Show_Integer_Array`. It could be a
range from 1 to 5 as used for variable :ada:`A_5` of the
:ada:`Using_Unconstrained_Type` procedure, or it could be a range from 1 to 10
as used for variable :ada:`A_10`, or it could be anything else. Although the
parameter :ada:`A` of :ada:`Show_Integer_Array` is unconstrained, both calls to
:ada:`Show_Integer_Array` |mdash| in :ada:`Using_Unconstrained_Type` procedure
|mdash| use constrained objects.

Note that we could call the :ada:`Show_Integer_Array` procedure above with
another unconstrained parameter. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types

    with Unconstrained_Types; use Unconstrained_Types;

    procedure Show_Integer_Array_Header
      (AA : Integer_Array;
       HH : String);

    with Ada.Text_IO;         use Ada.Text_IO;
    with Show_Integer_Array;

    procedure Show_Integer_Array_Header
      (AA : Integer_Array;
       HH : String)
    is
    begin
       Put_Line (HH);
       Show_Integer_Array (AA);
    end Show_Integer_Array_Header;

    with Unconstrained_Types; use Unconstrained_Types;

    with Show_Integer_Array_Header;

    procedure Using_Unconstrained_Type is
       A_5  : constant Integer_Array (1 .. 5)  :=
                (1, 2, 3, 4, 5);
       A_10 : constant Integer_Array (1 .. 10) :=
                (1, 2, 3, 4, 5, others => 99);
    begin
       Show_Integer_Array_Header (A_5,
                                  "First example");
       Show_Integer_Array_Header (A_10,
                                  "Second example");
    end Using_Unconstrained_Type;

In this case, we're calling the :ada:`Show_Integer_Array` procedure with
another unconstrained parameter (the :ada:`AA` parameter). However, although we
could have a long *chain* of procedure calls using indefinite types in their
parameters, we still use a (definite) object at the beginning of this chain.
For example, for the :ada:`A_5` object, we have this chain:

::

    A_5

        ==> Show_Integer_Array_Header (AA => A_5,
                                       ...);

            ==> Show_Integer_Array (A => AA);

Therefore, at this specific call to :ada:`Show_Integer_Array`, even though
:ada:`A` is declared as a parameter of indefinite type, the actual argument
is of definite type because :ada:`A_5` is constrained |mdash| and, thus, of
definite type.

Note that we can declare variables based on parameters of indefinite type. For
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Definite_Indefinite_Subtypes.Indefinite_Types

    with Unconstrained_Types; use Unconstrained_Types;

    procedure Show_Integer_Array_Plus
      (A : Integer_Array;
       V : Integer);

    with Show_Integer_Array;

    procedure Show_Integer_Array_Plus
      (A : Integer_Array;
       V : Integer)
    is
       A_Plus : Integer_Array (A'Range);
    begin
       for I in A_Plus'Range loop
          A_Plus (I) := A (I) + V;
       end loop;
       Show_Integer_Array (A_Plus);
    end Show_Integer_Array_Plus;

    with Unconstrained_Types; use Unconstrained_Types;

    with Show_Integer_Array_Plus;

    procedure Using_Unconstrained_Type is
       A_5 : constant Integer_Array (1 .. 5) :=
               (1, 2, 3, 4, 5);
    begin
       Show_Integer_Array_Plus (A_5, 5);
    end Using_Unconstrained_Type;

In the :ada:`Show_Integer_Array_Plus` procedure, we're declaring :ada:`A_Plus`
based on the range of :ada:`A`, which is itself of indefinite type. However,
since the object passed as an argument to :ada:`Show_Integer_Array_Plus` must
have a constraint, :ada:`A_Plus` will also be constrained. For example, in the
call to :ada:`Show_Integer_Array_Plus` using :ada:`A_5` as an argument, the
declaration of :ada:`A_Plus` becomes :ada:`A_Plus : Integer_Array (1 .. 5);`.
Therefore, it becomes clear that the compiler needs to allocate five elements
for :ada:`A_Plus`.

We'll see later how definite and indefinite types apply to
:ref:`formal parameters <Adv_Ada_Formal_Definite_Indefinite_Subtypes>`.

.. admonition:: In the Ada Reference Manual

    - :arm22:`3.3 Objects and Named Numbers <3-3>`


.. _Adv_Ada_Incomplete_Types:

Incomplete types
----------------

Incomplete types |mdash| as the name suggests |mdash| are types that have
missing information in their declaration. This is a simple example:

.. code-block:: ada

    type Incomplete;

Because this type declaration is incomplete, we need to provide the missing
information at some later point. Consider the incomplete type :ada:`R` in the
following example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Incomplete_Types.Incomplete_Types

    package Incomplete_Type_Example is

       type R;
       --  Incomplete type declaration!

       type R is record
          I : Integer;
       end record;
       --  type R is now complete!

    end Incomplete_Type_Example;

The first declaration of type :ada:`R` is incomplete. However, in the second
declaration of :ada:`R`, we specify that :ada:`R` is a record. By providing
this missing information, we're completing the type declaration of :ada:`R`.

It's also possible to declare an incomplete type in the private part of a
package specification and its complete form in the package body. Let's rewrite
the example above accordingly:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Incomplete_Types.Incomplete_Types_2

    package Incomplete_Type_Example is

    private

       type R;
       --  Incomplete type declaration!

    end Incomplete_Type_Example;

    package body Incomplete_Type_Example is

       type R is record
          I : Integer;
       end record;
       --  type R is now complete!

    end Incomplete_Type_Example;

A typical application of incomplete types is to create linked lists using
:ref:`access types <Adv_Ada_Access_Types_Terminology>`
based on those incomplete types. This kind of type is called
a recursive type. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Incomplete_Types.Linked_List_Example

    package Linked_List_Example is

       type Integer_List;

       type Next is access Integer_List;

       type Integer_List is record
          I : Integer;
          N : Next;
       end record;

    end Linked_List_Example;

Here, the :ada:`N` component of :ada:`Integer_List` is essentially giving us
access to the next element of :ada:`Integer_List` type. Because the :ada:`Next`
type is both referring to the :ada:`Integer_List` type and being used in the
declaration of the :ada:`Integer_List` type, we need to start with an
incomplete declaration of the :ada:`Integer_List` type and then complete it
after the declaration of :ada:`Next`.

Incomplete types are useful to declare
:ref:`mutually dependent types <Adv_Ada_Mutually_Dependent_Types>`, as we'll
see later on. We can also have formal incomplete types, as
we'll discuss :ref:`later <Adv_Ada_Formal_Incomplete_Types>`.

.. admonition:: In the Ada Reference Manual

    - :arm22:`3.10.1 Incomplete Type Declarations <3-10-1>`


.. _Adv_Ada_Type_View:

Type view
---------

Ada distinguishes between the partial and the full view of a type. The full
view is a type declaration that contains all the information needed by the
compiler. For example, the following declaration of type :ada:`R` represents
the full view of this type:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Type_View.Full_View

    package Full_View is

       --  Full view of the R type:
       type R is record
          I : Integer;
       end record;

    end Full_View;

    procedure Show_Conversion is
       Int_Var     : Int     := 1;
       Integer_Var : Integer := 2;
    begin
       --  Int to Integer conversion
       Integer_Var := Integer (Int_Var);

       Put_Line ("Integer_Var : "
                 & Integer_Var'Image);

       --  Int to Integer conversion
       --  as an actual parameter
       Integer_Var := Double (Integer (Int_Var));

       Put_Line ("Integer_Var : "
                 & Integer_Var'Image);

       --  Integer to Int conversion
       --  using an expression
       Int_Var     := Int (Integer_Var * 2);

       Put_Line ("Int_Var :     "
                 & Int_Var'Image);
    end Show_Conversion;

In the :ada:`Show_Conversion` procedure from this example, we first convert
from :ada:`Int` to :ada:`Integer`. Then, we do the same conversion while
providing the resulting value as an actual parameter for the :ada:`Double`
function. Finally, we convert the :ada:`Integer_Var * 2` expression from
:ada:`Integer` to :ada:`Int`.

Note that the converted value must conform to any constraints that the target
type might have. In the example above, :ada:`Int` has a predicate that dictates
that its value cannot be zero. This (dynamic) predicate is checked at runtime,
so an exception is raised if it fails:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Root_Derived_Type_Conversion
    :class: ada-run-expect-failure

    with Ada.Text_IO;     use Ada.Text_IO;
    with Custom_Integers; use Custom_Integers;

    procedure Show_Conversion is
       Int_Var     : Int;
       Integer_Var : Integer;
    begin
       Integer_Var := 0;
       Int_Var     := Int (Integer_Var);

       Put_Line ("Int_Var : "
                 & Int_Var'Image);
    end Show_Conversion;

In this case, the conversion from :ada:`Integer` to :ada:`Int` fails because,
while zero is a valid integer value, it doesn't obey :ada:`Int`\'s predicate.


Numeric type conversion
^^^^^^^^^^^^^^^^^^^^^^^

A typical conversion is the one between integer and floating-point values. For
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Numeric_Type_Conversion

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Conversion is
       F : Float   := 1.0;
       I : Integer := 2;
    begin
       I := Integer (F);

       Put_Line ("I : "
                 & I'Image);

       I := 4;
       F := Float (I);

       Put_Line ("F :   "
                 & F'Image);
    end Show_Conversion;

Also, we can convert between fixed-point types and floating-point or integer
types:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Numeric_Type_Conversion

    package Fixed_Point_Defs is
       S     : constant := 32;
       Exp   : constant := 15;
       D     : constant := 2.0 ** (-S + Exp + 1);

       type TQ15_31 is delta D
         range -1.0 * 2.0 ** Exp ..
                1.0 * 2.0 ** Exp - D;

       pragma Assert (TQ15_31'Size = S);
    end Fixed_Point_Defs;

    with Fixed_Point_Defs; use Fixed_Point_Defs;
    with Ada.Text_IO;      use Ada.Text_IO;

    procedure Show_Conversion is
       F  : Float;
       FP : TQ15_31;
       I  : Integer;
    begin
       FP := TQ15_31 (10.25);
       I  := Integer (FP);

       Put_Line ("FP : "
                 & FP'Image);
       Put_Line ("I : "
                 & I'Image);

       I  := 128;
       FP := TQ15_31 (I);
       F  := Float (FP);

       Put_Line ("FP : "
                 & FP'Image);
       Put_Line ("F :   "
                 & F'Image);
    end Show_Conversion;

As we can see in the examples above, converting between different numeric types
works in all directions. (Of course, rounding is applied when converting from
floating-point to integer types, but this is expected.)


Enumeration conversion
^^^^^^^^^^^^^^^^^^^^^^

We can also convert between an enumeration type and a type derived from it:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Enumeration_Type_Conversion

    package Custom_Enumerations is

       type Priority is (Low, Mid, High);

       type Important_Priority is new
         Priority range Mid .. High;

    end Custom_Enumerations;

    with Ada.Text_IO;         use Ada.Text_IO;
    with Custom_Enumerations; use Custom_Enumerations;

    procedure Show_Conversion is
       P  : Priority           := Low;
       IP : Important_Priority := High;
    begin
       P := Priority (IP);

       Put_Line ("P:  "
                 & P'Image);

       P  := Mid;
       IP := Important_Priority (P);

       Put_Line ("IP: "
                 & IP'Image);
    end Show_Conversion;

In this example, we have the :ada:`Priority` type and the derived type
:ada:`Important_Priority`. As expected, the conversion works fine when the
converted value is in the range of the target type. If not, an exception is
raised:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Enumeration_Type_Conversion
    :class: ada-run-expect-failure

    with Ada.Text_IO;         use Ada.Text_IO;
    with Custom_Enumerations; use Custom_Enumerations;

    procedure Show_Conversion is
       P  : Priority;
       IP : Important_Priority;
    begin
       P  := Low;
       IP := Important_Priority (P);

       Put_Line ("IP: "
                 & IP'Image);
    end Show_Conversion;

In this example, an exception is raised because :ada:`Low` is not in the :ada:`Important_Priority` type's range.


Array conversion
^^^^^^^^^^^^^^^^

Similarly, we can convert between array types. For example, if we have the
array type :ada:`Integer_Array` and its derived type
:ada:`Derived_Integer_Array`, we can convert between those array types:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Array_Type_Conversion switches=Compiler(-gnat2022);

    package Custom_Arrays is

       type Integer_Array is
         array (Positive range <>) of Integer;

       type Derived_Integer_Array is new
         Integer_Array;

    end Custom_Arrays;

    with Ada.Text_IO;   use Ada.Text_IO;
    with Custom_Arrays; use Custom_Arrays;

    procedure Show_Conversion is
       subtype Common_Range is Positive range 1 .. 3;

       AI : Integer_Array (Common_Range);
       AI_D : Derived_Integer_Array (Common_Range);
    begin
       AI_D := [1, 2, 3];
       AI := Integer_Array (AI_D);

       Put_Line ("AI: "
                 & AI'Image);

       AI   := [4, 5, 6];
       AI_D := Derived_Integer_Array (AI);

       Put_Line ("AI_D: "
                 & AI_D'Image);
    end Show_Conversion;

Note that both arrays must have the same number of components in order for the
conversion to be successful. (Sliding is fine, though.) In this example, both
arrays have the same range: :ada:`Common_Range`.

We can also convert between array types that aren't derived one from the
other. As long as the components and the index subtypes are of the same type,
the conversion between those types is possible. To be more precise, these are
the requirements for the array conversion to be accepted:

- The component types must be the same type.

- The index types (or subtypes) must be the same or, at least, convertible.

- The dimensionality of the arrays must be the same.

- The bounds must be compatible (but not necessarily equal).

Converting between different array types can be very handy, especially when
we're dealing with array types that were not declared in the same package. For
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Array_Type_Conversion switches=Compiler(-gnat2022);

    package Custom_Arrays_1 is

       type Integer_Array_1 is
         array (Positive range <>) of Integer;

       type Float_Array_1 is
         array (Positive range <>) of Float;

    end Custom_Arrays_1;

    package Custom_Arrays_2 is

       type Integer_Array_2 is
         array (Positive range <>) of Integer;

       type Float_Array_2 is
         array (Positive range <>) of Float;

    end Custom_Arrays_2;

    with Ada.Text_IO;     use Ada.Text_IO;
    with Custom_Arrays_1; use Custom_Arrays_1;
    with Custom_Arrays_2; use Custom_Arrays_2;

    procedure Show_Conversion is
       subtype Common_Range is Positive range 1 .. 3;

       AI_1 : Integer_Array_1 (Common_Range);
       AI_2 : Integer_Array_2 (Common_Range);
       AF_1 : Float_Array_1 (Common_Range);
       AF_2 : Float_Array_2 (Common_Range);
    begin
       AI_2 := [1, 2, 3];
       AI_1 := Integer_Array_1 (AI_2);

       Put_Line ("AI_1: "
                 & AI_1'Image);

       AI_1 := [4, 5, 6];
       AI_2 := Integer_Array_2 (AI_1);

       Put_Line ("AI_2: "
                 & AI_2'Image);

       --  ERROR: Cannot convert arrays whose
       --         components have different types:
       --
       --  AF_1 := Float_Array_1 (AI_1);
       --
       --  Instead, use array aggregate where each
       --  component is converted from integer to
       --  float:
       --
       AF_1 := [for I in AF_1'Range =>
                  Float (AI_1 (I))];

       Put_Line ("AF_1: "
                 & AF_1'Image);

       AF_2 := Float_Array_2 (AF_1);

       Put_Line ("AF_2: "
                 & AF_2'Image);
    end Show_Conversion;

As we can see in this example, the fact that :ada:`Integer_Array_1` and
:ada:`Integer_Array_2` have the same component type (:ada:`Integer`) allows us
to convert between them. The same applies to the :ada:`Float_Array_1` and
:ada:`Float_Array_2` types.

A conversion is not possible when the component types don't match. Even though
we can convert between integer and floating-point types, we cannot convert an
array of integers to an array of floating-point directly. Therefore, we cannot
write a statement such as :ada:`AF_1 := Float_Array_1 (AI_1);`.

However, when the components don't match, we can of course implement the array
conversion by converting the individual components. For the example above, we
used an iterated component association in an array aggregate:
:ada:`[for I in AF_1'Range => Float (AI_1 (I))];`. (We discuss this topic later
:ref:`in another chapter <Adv_Ada_Array_Aggregates>`.)

We may also encounter array types originating from the instantiation of generic
packages. In this case as well, we can use array conversions. Consider the
following generic package:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Generic_Array_Type_Conversion switches=Compiler(-gnat2022);

    generic
       type T is private;
    package Custom_Arrays is
       type T_Array is
         array (Positive range <>) of T;
    end Custom_Arrays;

We could instantiate this generic package and reuse parts of the previous code
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Generic_Array_Type_Conversion switches=Compiler(-gnat2022);

    with Ada.Text_IO;   use Ada.Text_IO;
    with Custom_Arrays;

    procedure Show_Conversion is
       package CA_Int_1 is
         new Custom_Arrays (T => Integer);
       package CA_Int_2 is
         new Custom_Arrays (T => Integer);

       subtype Common_Range is Positive range 1 .. 3;

       AI_1 : CA_Int_1.T_Array (Common_Range);
       AI_2 : CA_Int_2.T_Array (Common_Range);
    begin
       AI_2 := [1, 2, 3];
       AI_1 := CA_Int_1.T_Array (AI_2);

       Put_Line ("AI_1: "
                 & AI_1'Image);

       AI_1 := [4, 5, 6];
       AI_2 := CA_Int_2.T_Array (AI_1);

       Put_Line ("AI_2: "
                 & AI_2'Image);
    end Show_Conversion;

As we can see in this example, each of the instantiated :ada:`CA_Int_1` and
:ada:`CA_Int_2` packages has a :ada:`T_Array` type. Even though these
:ada:`T_Array` types have the same name, they're actually completely unrelated
types. However, we can still convert between them in the same way as we did in
the previous code examples.


.. _Adv_Ada_View_Conversion:

View conversion
~~~~~~~~~~~~~~~

As mentioned before, view conversions just allow names to be converted. Thus,
we cannot use expressions in this case.

Note that a view conversion never changes the value during the conversion. We
could say that a view conversion is simply making us *view* an object from a
different angle. The object itself is still the same for both the original and
the target types.

For example, consider this package:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Tagged_Types_View

    package Some_Tagged_Types is

       type T is tagged record
          A : Integer;
       end record;

       type T_Derived is new T with record
          B : Float;
       end record;

       Obj : T_Derived;

    end Some_Tagged_Types;

Here, :ada:`Obj` is an object of type :ada:`T_Derived`. When we *view* this
object, we notice that it has two components: :ada:`A` and :ada:`B`. However,
we could *view* this object as being of type :ada:`T`. From that perspective,
this object only has one component: :ada:`A`. (Note that changing the
perspective doesn't change the object itself.) Therefore, a view conversion
from :ada:`T_Derived` to :ada:`T` just makes us *view* the object :ada:`Obj`
from a different angle.

In this sense, a view conversion changes the view of a given object to the
target type's view, both in terms of components that exist and operations that
are available. It doesn't really change anything at all in the value itself.

There are basically two kinds of view conversions: the ones using tagged types
and the ones using untagged types. We discuss these kinds of conversion in this
section.

View conversion of tagged types
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

A conversion between tagged types is a view conversion. Let's consider a
typical code example that declares one, two and three-dimensional points:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Tagged_Type_Conversion

    package Points is

       type Point_1D is tagged record
          X : Float;
       end record;

       procedure Display (P : Point_1D);

       type Point_2D is new Point_1D with record
          Y : Float;
       end record;

       procedure Display (P : Point_2D);

       type Point_3D is new Point_2D with record
          Z : Float;
       end record;

       procedure Display (P : Point_3D);

    end Points;

    with Ada.Text_IO; use Ada.Text_IO;

    package body Points is

       procedure Display (P : Point_1D) is
       begin
          Put_Line ("(X => " & P.X'Image & ")");
       end Display;

       procedure Display (P : Point_2D) is
       begin
          Put_Line ("(X => " & P.X'Image
                    & ", Y => " & P.Y'Image & ")");
       end Display;

       procedure Display (P : Point_3D) is
       begin
          Put_Line ("(X => " & P.X'Image
                    & ", Y => " & P.Y'Image
                    & ", Z => " & P.Z'Image & ")");
       end Display;

    end Points;

We can use the types from the :ada:`Points` package and convert between each
other:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Tagged_Type_Conversion

    with Ada.Text_IO; use Ada.Text_IO;
    with Points;      use Points;

    procedure Show_Conversion is
       P_1D : Point_1D;
       P_3D : Point_3D;
    begin
       P_3D := (X => 0.1, Y => 0.5, Z => 0.3);
       P_1D := Point_1D (P_3D);

       Put ("P_3D : ");
       Display (P_3D);

       Put ("P_1D : ");
       Display (P_1D);
    end Show_Conversion;

In this example, as expected, we're able to convert from the :ada:`Point_3D`
type (which has three components) to the :ada:`Point_1D` type, which has only
one component.


View conversion of untagged types
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

For untagged types, a view conversion is the one that happens when we have an
object of an untagged type as an actual parameter for a formal :ada:`in out`
or :ada:`out` parameter.

Let's see a code example. Consider the following simple procedure:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Untagged_Type_View_Conversion

    procedure Double (X : in out Float);

    procedure Double (X : in out Float) is
    begin
       X := X * 2.0;
    end Double;

The :ada:`Double` procedure has an :ada:`in out` parameter of :ada:`Float`
type. We can call this procedure using an integer variable :ada:`I` as the
actual parameter. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Untagged_Type_View_Conversion

    with Ada.Text_IO; use Ada.Text_IO;
    with Double;

    procedure Show_Conversion is
       I : Integer;
    begin
       I := 2;
       Put_Line ("I : "
                 & I'Image);

       --  Calling Double with
       --  Integer parameter:
       Double (Float (I));
       Put_Line ("I : "
                 & I'Image);
    end Show_Conversion;

In this case, the :ada:`Float (I)` conversion in the call to :ada:`Double`
creates a temporary floating-point variable. This is the same as if we had
written the following code:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Untagged_Type_View_Conversion

    with Ada.Text_IO; use Ada.Text_IO;
    with Double;

    procedure Show_Conversion is
       I : Integer;
    begin
       I := 2;
       Put_Line ("I : "
                 & I'Image);

       declare
          F : Float := Float (I);
       begin
          Double (F);
          I := Integer (F);
       end;
       Put_Line ("I : "
                 & I'Image);
    end Show_Conversion;

In this sense, the view conversion that happens in :ada:`Double (Float (I))`
can be considered syntactic sugar, as it allows us to elegantly write two
conversions in a single statement.


Implicit conversions
~~~~~~~~~~~~~~~~~~~~

Implicit conversions are only possible when we have a type :ada:`T` and a
subtype :ada:`S` related to the :ada:`T` type. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Implicit_Subtype_Conversion

    package Custom_Integers is

       type Int is new Integer
         with Dynamic_Predicate => Int /= 0;

       subtype Sub_Int_1 is Integer
         with Dynamic_Predicate => Sub_Int_1 /= 0;

       subtype Sub_Int_2 is Sub_Int_1
         with Dynamic_Predicate => Sub_Int_2 /= 1;

    end Custom_Integers;

    with Ada.Text_IO;     use Ada.Text_IO;
    with Custom_Integers; use Custom_Integers;

    procedure Show_Conversion is
       Int_Var       : Int;
       Sub_Int_1_Var : Sub_Int_1;
       Sub_Int_2_Var : Sub_Int_2;
       Integer_Var   : Integer;
    begin
       Integer_Var := 5;
       Int_Var     := Int (Integer_Var);

       Put_Line ("Int_Var :       "
                 & Int_Var'Image);

       --  Implicit conversions:
       --  no explicit conversion required!
       Sub_Int_1_Var := Integer_Var;
       Sub_Int_2_Var := Integer_Var;

       Put_Line ("Sub_Int_1_Var : "
                 & Sub_Int_1_Var'Image);
       Put_Line ("Sub_Int_2_Var : "
                 & Sub_Int_2_Var'Image);
    end Show_Conversion;

In this example, we declare the :ada:`Int` type and the :ada:`Sub_Int_1` and
:ada:`Sub_Int_2` subtypes:

- the :ada:`Int` type is derived from the :ada:`Integer` type,

- :ada:`Sub_Int_1` is a subtype of the :ada:`Integer` type, and

- :ada:`Sub_Int_2` is a subtype of the :ada:`Sub_Int_1` subtype.

We need an explicit conversion when converting between the :ada:`Integer` and
:ada:`Int` types. However, as the conversion is implicit for subtypes, we can
simply write :ada:`Sub_Int_1_Var := Integer_Var;`. (Of course, writing the
explicit conversion :ada:`Sub_Int_1 (Integer_Var)` in the assignment is
possible as well.) Also, the same applies to the :ada:`Sub_Int_2` subtype: we
can write an implicit conversion in the :ada:`Sub_Int_2_Var := Integer_Var;`
statement.


Conversion of other types
~~~~~~~~~~~~~~~~~~~~~~~~~

For other kinds of types, such as records, a direct conversion as we've seen so
far isn't possible. In this case, we have to write a conversion function
ourselves. A common convention in Ada is to name this function
:ada:`To_Typename`. For example, if we want to convert from any type to
:ada:`Integer` or :ada:`Float`, we implement the :ada:`To_Integer` and
:ada:`To_Float` functions, respectively. (Obviously, because Ada supports
subprogram overloading, we can have multiple :ada:`To_Typename` functions for
different operand types.)

Let's see a code example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Other_Type_Conversions

    package Custom_Rec is

       type Rec is record
          X : Integer;
       end record;

       function To_Integer (R : Rec)
                            return Integer is
         (R.X);

    end Custom_Rec;

    with Ada.Text_IO; use Ada.Text_IO;
    with Custom_Rec;  use Custom_Rec;

    procedure Show_Conversion is
       R : Rec;
       I : Integer;
    begin
       R := (X => 2);
       I := To_Integer (R);

       Put_Line ("I : " & I'Image);
    end Show_Conversion;

In this example, we have the :ada:`To_Integer` function that converts from the
:ada:`Rec` type to the :ada:`Integer` type.

.. admonition:: In other languages

    In C++, you can define conversion operators to cast between objects of
    different classes. Also, you can overload the :cpp:`=` operator.
    Consider this example:

    .. code-block:: cpp

        #include <iostream>

        class T1 {
        public:
            T1 (float x) :
              x(x) {}

            // If class T3 is declared before class
            // T1, we can overload the "=" operator.
            //
            // void operator=(T3 v) {
            //     x = static_cast<float>(v);
            // }

            void display();
        private:
           float x;
        };

        class T3 {
        public:
            T3 (float x, float y, float z) :
              x(x), y(y), z(z) {}

            // implicit conversion
            operator float() const {
                return (x + y + z) / 3.0;
            }

            // implicit conversion
            //
            // operator T1() const {
            //     return T1((x + y + z) / 3.0);
            // }

            // explicit conversion (C++11)
            explicit operator T1() const {
                return T1(float(*this));
            }

            void display();

        private:
            float x, y, z;
        };

        void T1::display()
        {
            std::cout << "(x => " << x
                      << ")" << std::endl;
        }

        void T3::display()
        {
            std::cout << "(x => " << x
                      << "y => "  << y
                      << "z => "  << z
                      << ")" << std::endl;
        }

        int main ()
        {
            const T3 t_3 (0.5, 0.4, 0.6);
            T1 t_1 (0.0);
            float f;

            // Implicit conversion
            f = t_3;

            std::cout << "f : " << f
                      << std::endl;

            // Explicit conversion
            f = static_cast<float>(t_3);

            // f = (float)t_3;

            std::cout << "f : " << f
                      << std::endl;

            // Explicit conversion
            t_1 = static_cast<T1>(t_3);

            // t_1 = (T1)t_3;

            std::cout << "t_1 : ";
            t_1.display();
            std::cout << std::endl;
        }

    Here, we're using :cpp:`operator float()` and :cpp:`operator T1()` to
    cast from an object of class :cpp:`T3` to a floating-point value and an
    object of class :cpp:`T1`, respectively. (If we switch the order and
    declare the :cpp:`T3` class before the :cpp:`T1` class, we could overload
    the :cpp:`=` operator, as you can see in the commented-out lines.)

    In Ada, this kind of conversion isn't available. Instead, we have to
    implement conversion functions such as the :ada:`To_Integer` function from
    the previous code example. This is the corresponding implementation:

    .. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Type_Conversion.Explicit_Rec_Conversion

        package Custom_Defs is

           type T1 is private;

           function Init (X : Float)
                          return T1;

           procedure Display (Obj : T1);

           type T3 is private;

           function Init (X, Y, Z : Float)
                          return T3;

           function To_Float (Obj : T3)
                              return Float;

           function To_T1 (Obj : T3)
                           return T1;

           procedure Display (Obj : T3);

        private
           type T1 is record
              X : Float;
           end record;

           function Init (X : Float)
                          return T1 is
             (X => X);

           type T3 is record
              X, Y, Z : Float;
           end record;

           function Init (X, Y, Z : Float)
                          return T3 is
             (X => X, Y => Y, Z => Z);

        end Custom_Defs;

        with Ada.Text_IO; use Ada.Text_IO;

        package body Custom_Defs is

           procedure Display (Obj : T1) is
           begin
              Put_Line ("(X => "
                        & Obj.X'Image & ")");
           end Display;

           function To_Float (Obj : T3)
                              return Float is
             ((Obj.X + Obj.Y + Obj.Z) / 3.0);

           function To_T1 (Obj : T3)
                           return T1 is
             (Init (To_Float (Obj)));

           procedure Display (Obj : T3) is
           begin
              Put_Line ("(X => "    & Obj.X'Image
                        & ", Y => " & Obj.Y'Image
                        & ", Z => " & Obj.Z'Image
                        & ")");
           end Display;

        end Custom_Defs;

        with Ada.Text_IO; use Ada.Text_IO;
        with Custom_Defs; use Custom_Defs;

        procedure Show_Conversion is
           T_3 : constant T3 := Init (0.5, 0.4, 0.6);
           T_1 :          T1 := Init (0.0);
           F   : Float;
        begin
           --  Explicit conversion from
           --  T3 to Float type
           F := To_Float (T_3);

           Put_Line ("F : " & F'Image);

           --  Explicit conversion from
           --  T3 to T1 type
           T_1 := To_T1 (T_3);

           Put ("T_1 : ");
           Display (T_1);
        end Show_Conversion;

    In this example, we *translate* the casting operators from the C++ version
    by implementing the :ada:`To_Float` and :ada:`To_T1` functions.
    (In addition to that, we replace the C++ constructors by :ada:`Init`
    functions.)


.. _Adv_Ada_Qualified_Expressions:

Qualified Expressions
---------------------

We already saw qualified expressions in the
:ref:`Introduction to Ada <Intro_Ada_Qualified_Expressions>` course. As
mentioned there, a qualified expression specifies the exact type or subtype
that the target expression will be resolved to, and it can be either any
expression in parentheses, or an aggregate:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Qualified_Expressions.Example

    package Simple_Integers is

       type Int is new Integer;

       subtype Int_Not_Zero is Int
         with Dynamic_Predicate => Int_Not_Zero /= 0;

    end Simple_Integers;

    with Simple_Integers; use Simple_Integers;

    procedure Show_Qualified_Expressions is
       I : Int;
    begin
       --  Using qualified expression Int'(N)
       I := Int'(0);
    end Show_Qualified_Expressions;

Here, the qualified expression :ada:`Int'(0)` indicates that the value zero is
of :ada:`Int` type.

.. admonition:: In the Ada Reference Manual

    - :arm22:`4.7 Qualified Expressions <4-7>`


Verifying subtypes
~~~~~~~~~~~~~~~~~~

.. note::

   This feature was introduced in Ada 2022.

We can use qualified expressions to verify a subtype's predicate:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Qualified_Expressions.Example
    :class: ada-run-expect-failure

    with Simple_Integers; use Simple_Integers;

    procedure Show_Qualified_Expressions is
       I : Int;
    begin
       I := Int_Not_Zero'(0);
    end Show_Qualified_Expressions;

Here, the qualified expression :ada:`Int_Not_Zero'(0)` checks the dynamic
predicate of the subtype. (This predicate check fails at runtime.)


.. _Adv_Ada_Default_Initial_Values:

Default initial values
----------------------

In the
:ref:`Introduction to Ada course <Intro_Ada_Record_Default_Values>`,
we've seen that record components can have default values. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults_1

    package Defaults is

       type R is record
         X : Positive := 1;
         Y : Positive := 10;
       end record;

    end Defaults;

In this section, we'll extend the concept of default values to other kinds of
type declarations, such as scalar types and arrays.

.. _Adv_Ada_Default_Value:

To assign a default value for a scalar type declaration |mdash| such as an
enumeration and a new integer |mdash|, we use the :ada:`Default_Value` aspect:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults_2

    package Defaults is

       type E is (E1, E2, E3)
         with Default_Value => E1;

       type T is new Integer
         with Default_Value => -1;

    end Defaults;

Note that we cannot specify a default value for a subtype:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults_3
    :class: ada-expect-compile-error

    package Defaults is

       subtype T is Integer
         with Default_Value => -1;
       --  ERROR!!

    end Defaults;

.. _Adv_Ada_Default_Component_Value:

For array types, we use the :ada:`Default_Component_Value` aspect:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults_4

    package Defaults is

       type Arr is
         array (Positive range <>) of Integer
           with Default_Component_Value => -1;

    end Defaults;

This is a package containing the declarations we've just seen:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults

    package Defaults is

       type E is (E1, E2, E3)
         with Default_Value => E1;

       type T is new Integer
         with Default_Value => -1;

       --  We cannot specify default
       --  values for subtypes:
       --
       --  subtype T is Integer
       --    with Default_Value => -1;

       type R is record
         X : Positive := 1;
         Y : Positive := 10;
       end record;

       type Arr is
         array (Positive range <>) of Integer
           with Default_Component_Value => -1;

    end Defaults;

In the example below, we declare variables of the types from the
:ada:`Defaults` package:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.Default_Initial_Values.Defaults

    with Ada.Text_IO; use Ada.Text_IO;
    with Defaults; use Defaults;

    procedure Use_Defaults is
       E1 : E;
       T1 : T;
       R1 : R;
       A1 : Arr (1 .. 5);
    begin
       Put_Line ("Enumeration:  "
                 & E'Image (E1));
       Put_Line ("Integer type: "
                 & T'Image (T1));
       Put_Line ("Record type:  "
                 & Positive'Image (R1.X)
                 & ", "
                 & Positive'Image (R1.Y));

       Put ("Array type:   ");
       for V of A1 loop
          Put (Integer'Image (V) & " ");
       end loop;
       New_Line;
    end Use_Defaults;

As we see in the :ada:`Use_Defaults` procedure, all variables still have their
default values, since we haven't assigned any value to them.

.. admonition:: In the Ada Reference Manual

    - :arm22:`3.5 Scalar Types <3-5>`
    - :arm22:`3.6 Array Types <3-6>`


Deferred Constants
------------------

Deferred constants are declarations where the value of the constant is not
specified immediately, but rather *deferred* to a later point. In that sense,
if a constant declaration is deferred, it is actually declared twice:

1. in the deferred constant declaration, and
2. in the full constant declaration.

The simplest form of deferred constant is the one that has a full constant
declaration in the private part of the package specification. For example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Deferred_Constants.Deferred_Constant_Private

    package Deferred_Constants is

       type Speed is new Long_Float;

       Light : constant Speed;
       --      ^ deferred constant declaration

    private

       Light : constant Speed := 299_792_458.0;
       --      ^ full constant declaration

    end Deferred_Constants;

Another form of deferred constant is the one that imports a constant from an
external implementation |mdash| using the :ada:`Import` keyword. We can use
this to import a constant declaration from an implementation in C. For example,
we can declare the :c:`light` constant in a C file:

.. code:: c no_button manual_chop project=Courses.Advanced_Ada.Data_Types.Types.Deferred_Constants.Deferred_Constant_C
    :class: ada-syntax-only

    !constants.c
    double light = 299792458.0;

Then, we can import this constant in the :ada:`Deferred_Constants` package:

.. code:: ada no_button project=Courses.Advanced_Ada.Data_Types.Types.Deferred_Constants.Deferred_Constant_C
    :class: ada-syntax-only

    package Deferred_Constants is

       type Speed is new Long_Float;

       Light : constant Speed with
         Import, Convention => C;
       --  ^^^^ deferred constant
       --       declaration; imported
       --       from C file

    end Deferred_Constants;

In this case, we don't have a full declaration in the :ada:`Deferred_Constants`
package, as the :ada:`Light` constant is imported from the :file:`constants.c`
file.

As a rule, the deferred and the full declarations should match |mdash| except,
of course, for the actual value that is missing in the deferred declaration.
For instance, we're not allowed to use different types in both declarations.
However, we may use a subtype in the full declaration |mdash| as long as it's
compatible with the type that was used in the deferred declaration. For
example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Deferred_Constants.Deferred_Constant_Subtype

    package Deferred_Constants is

       type Speed is new Long_Float;

       subtype Positive_Speed is
         Speed range 0.0 .. Speed'Last;

       Light : constant Speed;
       --      ^ deferred constant declaration

    private

       Light : constant Positive_Speed :=
                 299_792_458.0;
       --      ^ full constant declaration
       --        using a subtype

    end Deferred_Constants;

Here, we're using the :ada:`Speed` type in the deferred declaration of the
:ada:`Light` constant, but we're using the :ada:`Positive_Speed` subtype in
the full declaration.

A useful application of deferred constants is when the value of the constant is
calculated using entities not meant to be compile-time visible to clients.
As such, these other entities are only visible in the private part of the
package, so that's where the value of the deferred constant must be computed.
For example, the full constant declaration may be computed by a call to an
expression function:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.Deferred_Constants.Deferred_Constant_Function

    package Deferred_Constants is

       type Speed is new Long_Float;

       Light : constant Speed;
       --      ^ deferred constant declaration

    private

       function Calculate_Light return Speed is
         (299_792_458.0);

       Light : constant Speed := Calculate_Light;
       --      ^ full constant declaration
       --        calling a private function

    end Deferred_Constants;

Here, we call the :ada:`Calculate_Light` function |mdash| declared in the
private part of the :ada:`Deferred_Constants` package |mdash| for the full
declaration of the :ada:`Light` constant.

.. admonition:: In the Ada Reference Manual

    - :arm22:`7.4 Deferred Constants <7-4>`


.. _Adv_Ada_User_Defined_Literals:

User-defined literals
---------------------

.. note::

   This feature was introduced in Ada 2022.

Any type definition has a kind of literal associated with it. For example,
integer types are associated with integer literals. Therefore, we can
initialize an object of integer type with an integer literal:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Simple_Integer_Literal

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Simple_Integer_Literal is
       V : Integer;
    begin
       V := 10;

       Put_Line (Integer'Image (V));
    end Simple_Integer_Literal;

Here, :ada:`10` is the integer literal that we use to initialize the integer
variable :ada:`V`. Other examples of literals are real literals and string
literals, as we'll see later.

When we declare an enumeration type, we limit the set of literals that we can
use to initialize objects of that type:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Simple_Enumeration

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Simple_Enumeration is
       type Activation_State is (Unknown, Off, On);

       S : Activation_State;
    begin
       S := On;
       Put_Line (Activation_State'Image (S));
    end Simple_Enumeration;

For objects of :ada:`Activation_State` type, such as :ada:`S`, the only
possible literals that we can use are :ada:`Unknown`, :ada:`Off` and :ada:`On`.
In this sense, types have a constrained set of literals that can be used for
objects of that type.

User-defined literals allow us to extend this set of literals. We could, for
example, extend the type declaration of :ada:`Activation_State` and allow the
use of integer literals for objects of that type. In this case, we need to use
the :ada:`Integer_Literal` aspect and specify a function that implements the
conversion from literals to the type we're declaring. For this conversion from
integer literals to the :ada:`Activation_State` type, we could specify that 0
corresponds to :ada:`Off`, 1 corresponds to :ada:`On` and other values
correspond to :ada:`Unknown`. We'll see the corresponding implementation later.

These are the three kinds of literals and their corresponding aspect:

+----------+----------+-------------------------+
| Literal  | Example  | Aspect                  |
+==========+==========+=========================+
| Integer  |        1 | :ada:`Integer_Literal`  |
+----------+----------+-------------------------+
| Real     |      1.0 | :ada:`Real_Literal`     |
+----------+----------+-------------------------+
| String   |     "On" | :ada:`String_Literal`   |
+----------+----------+-------------------------+

For our previous :ada:`Activation_States` type, we could declare a function
:ada:`Integer_To_Activation_State` that converts integer literals to one of the
enumeration literals that we've specified for the :ada:`Activation_States`
type:

.. code:: ada no_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.User_Defined_Literals switches=Compiler(-gnat2022);

    package Activation_States is

       type Activation_State is (Unknown, Off, On)
         with Integer_Literal =>
                Integer_To_Activation_State;

       function Integer_To_Activation_State
         (S : String)
          return Activation_State;

    end Activation_States;

Based on this specification, we can now use an integer literal to initialize an
object :ada:`S` of :ada:`Activation_State` type:

.. code-block:: ada

    S : Activation_State := 1;

Note that we have a string parameter in the declaration of the
:ada:`Integer_To_Activation_State` function, even though the function itself is
only used to convert integer literals (but not string literals) to the
:ada:`Activation_State` type. It's our job to process that string parameter in
the implementation of the :ada:`Integer_To_Activation_State` function and
convert it to an integer value |mdash| using :ada:`Integer'Value`, for example:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.User_Defined_Literals switches=Compiler(-gnat2022);

    package body Activation_States is

       function Integer_To_Activation_State
         (S : String)
          return Activation_State is
       begin
          case Integer'Value (S) is
             when 0      => return Off;
             when 1      => return On;
             when others => return Unknown;
          end case;
       end Integer_To_Activation_State;

    end Activation_States;

Let's look at a complete example that makes use of all three kinds of literals:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Activation_States switches=Compiler(-gnat2022);

    package Activation_States is

       type Activation_State is (Unknown, Off, On)
         with String_Literal  =>
                To_Activation_State,
              Integer_Literal =>
                Integer_To_Activation_State,
              Real_Literal    =>
                Real_To_Activation_State;

       function To_Activation_State
         (S : Wide_Wide_String)
          return Activation_State;

       function Integer_To_Activation_State
         (S : String)
          return Activation_State;

       function Real_To_Activation_State
         (S : String)
          return Activation_State;

    end Activation_States;

    package body Activation_States is

       function To_Activation_State
         (S : Wide_Wide_String)
          return Activation_State
       is
       begin
          if S = "Off" then
             return Off;
          elsif S = "On" then
             return On;
          else
             return Unknown;
          end if;
       end To_Activation_State;

       function Integer_To_Activation_State
         (S : String)
          return Activation_State
       is
       begin
          case Integer'Value (S) is
             when 0      => return Off;
             when 1      => return On;
             when others => return Unknown;
          end case;
       end Integer_To_Activation_State;

       function Real_To_Activation_State
         (S : String)
          return Activation_State
       is
          V : constant Float := Float'Value (S);
       begin
          if V < 0.0 then
             return Unknown;
          elsif V < 1.0 then
             return Off;
          else
             return On;
          end if;
       end Real_To_Activation_State;

    end Activation_States;

    with Ada.Text_IO;       use Ada.Text_IO;
    with Activation_States; use Activation_States;

    procedure Activation_Examples is
       S : Activation_State;
    begin
       S := "Off";
       Put_Line ("String: Off  => "
                 & Activation_State'Image (S));

       S := 1;
       Put_Line ("Integer: 1   => "
                 & Activation_State'Image (S));

       S := 1.5;
       Put_Line ("Real:    1.5 => "
                 & Activation_State'Image (S));
    end Activation_Examples;

In this example, we're extending the declaration of the :ada:`Activation_State`
type to include string and real literals. For string literals, we use the
:ada:`To_Activation_State` function, which converts:

    - the :ada:`"Off"` string to :ada:`Off`,

    - the :ada:`"On"` string to :ada:`On`, and

    - any other string to :ada:`Unknown`.

For real literals, we use the :ada:`Real_To_Activation_State` function, which
converts:

    - any negative number to :ada:`Unknown`,

    - a value in the interval [0, 1) to :ada:`Off`, and

    - a value equal to or above 1.0 to :ada:`On`.

Note that the string parameter of the :ada:`To_Activation_State` function |mdash|
which converts string literals |mdash| is of :ada:`Wide_Wide_String` type, and
not of :ada:`String` type, as is the case for the other conversion functions.

In the :ada:`Activation_Examples` procedure, we show how we can initialize an
object of :ada:`Activation_State` type with all kinds of literals (string,
integer and real literals).

With the definition of the :ada:`Activation_State` type that we've seen in the
complete example, we can initialize an object of this type with an enumeration
literal or a string, as both forms are defined in the type specification:

.. code:: ada run_button main=using_string_literal.adb project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Activation_States switches=Compiler(-gnat2022);

    with Ada.Text_IO;       use Ada.Text_IO;
    with Activation_States; use Activation_States;

    procedure Using_String_Literal is
       S1 : constant Activation_State := On;
       S2 : constant Activation_State := "On";
    begin
       Put_Line (Activation_State'Image (S1));
       Put_Line (Activation_State'Image (S2));
    end Using_String_Literal;

Note we need to be very careful when designing conversion functions. For
example, the use of string literals may limit the kind of checks that we can
do. Consider the following misspelling of the :ada:`Off` literal:

.. code:: ada run_button main=misspelling_example.adb project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Activation_States switches=Compiler(-gnat2022);
    :class: ada-expect-compile-error

    with Ada.Text_IO;       use Ada.Text_IO;
    with Activation_States; use Activation_States;

    procedure Misspelling_Example is
       S : constant Activation_State :=
             Offf;
       --    ^ Error: Off is misspelled.
    begin
       Put_Line (Activation_State'Image (S));
    end Misspelling_Example;

As expected, the compiler detects this error. However, this error is accepted
when using the corresponding string literal:

.. code:: ada run_button main=misspelling_example.adb project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Activation_States switches=Compiler(-gnat2022);

    with Ada.Text_IO;       use Ada.Text_IO;
    with Activation_States; use Activation_States;

    procedure Misspelling_Example is
       S : constant Activation_State :=
             "Offf";
       --     ^ Error: Off is misspelled.
    begin
       Put_Line (Activation_State'Image (S));
    end Misspelling_Example;

Here, our implementation of :ada:`To_Activation_State` simply returns
:ada:`Unknown`. In some cases, this might be exactly the behavior that we want.
However, let's assume that we'd prefer better error handling instead. In this
case, we could change the implementation of :ada:`To_Activation_State` to check
all literals that we want to allow, and indicate an error otherwise |mdash| by
raising an exception, for example. Alternatively, we could specify this in the
preconditions of the conversion function:

.. code-block:: ada

       function To_Activation_State
         (S : Wide_Wide_String)
          return Activation_State
            with Pre => S = "Off"  or
                        S = "On"   or
                        S = "Unknown";

In this case, the precondition explicitly indicates which string literals are
allowed for the :ada:`To_Activation_State` function.

User-defined literals can also be used for more complex types, such as records.
For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Types.User_Defined_Literals.Record_Literals switches=Compiler(-gnat2022);

    package Silly_Records is

       type Silly is record
          X : Integer;
          Y : Float;
       end record
         with String_Literal => To_Silly;

       function To_Silly (S : Wide_Wide_String)
                          return Silly;
    end Silly_Records;

    package body Silly_Records is

       function To_Silly (S : Wide_Wide_String)
                          return Silly
       is
       begin
          if S = "Magic" then
             return (X => 42, Y => 42.0);
          else
             return (X => 0, Y => 0.0);
          end if;
       end To_Silly;

    end Silly_Records;

    with Ada.Text_IO;   use Ada.Text_IO;
    with Silly_Records; use Silly_Records;

    procedure Silly_Magic is
       R1 : Silly;
    begin
       R1 := "Magic";
       Put_Line (R1.X'Image & ", " & R1.Y'Image);
    end Silly_Magic;

In this example, when we initialize an object of :ada:`Silly` type with a
string, its components are:

- set to 42 when using the "Magic" string; or

- simply set to zero when using any other string.

Obviously, this example isn't particularly useful. However, the goal is to
show that this approach is useful for more complex types where a string literal
(or a numeric literal) might simplify handling those types. User-defined
literals let you design types in ways that, otherwise, would only be possible
when using a preprocessor or a domain-specific language.

.. admonition:: In the Ada Reference Manual

    - :arm22:`4.2.1 User-Defined Literals <4-2-1>`

We can use representation clauses to change the way the compiler handles
memory for a record type. For example, let's say we want to have an empty
storage unit between components :ada:`A` and :ada:`B`. We can use a
representation clause where we specify that component :ada:`B` starts at
position #5 instead of #4, leaving an empty byte after component :ada:`A` and
before component :ada:`B`:

.. graphviz::

    digraph foo {
        "Record_R" [
            label = "{ position | bits | component } |  { { { 0 | #0 .. 7 } | { 1 | #8 .. #15 } | { 2 | #16 .. #23 } | { 3 | #24 .. #31 } } | A } | { 4 |  |  } | { { { 5 | #0 .. 7 } | { 6 | #8 .. #15 } | { 7 | #16 .. #23 } | { 8 | #24 .. #31 } } | B }"
            shape = "record"
        ];
   }

This is the code that implements that:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Record_Representation_Storage_Clauses.Rep_Clauses_Empty_Byte

    package P is

       type R is record
          A : Integer;
          B : Integer;
       end record;

       for R use record
          A at 0 range 0 .. 31;
          B at 5 range 0 .. 31;
       end record;

    end P;

    with Ada.Text_IO; use Ada.Text_IO;

    with P;           use P;

    procedure Show_Empty_Byte is
    begin
       Put_Line ("R'Size:        "
                 & R'Size'Image);
       Put_Line ("R'Object_Size: "
                 & R'Object_Size'Image);
    end Show_Empty_Byte;

When running the application above, we see that, due to the extra byte in the
record representation, the sizes increase. On a typical 64-bit PC,
:ada:`R'Size` is now 72 bits, which reflects the additional eight bits that we
introduced between components :ada:`A` and :ada:`B`. Depending on the target
architecture, you may also see that :ada:`R'Object_Size` is now 96 bits, which
is the size the compiler selects as the most appropriate for this record type.
As we've mentioned in the previous section, we can use aspects to request a
specific size to the compiler. In this case, we could use the
:ada:`Object_Size` aspect:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Record_Representation_Storage_Clauses.Rep_Clauses_Empty_Byte

    package P is

       type R is record
          A : Integer;
          B : Integer;
       end record
         with Object_Size => 72;

       for R use record
          A at 0 range 0 .. 31;
          B at 5 range 0 .. 31;
       end record;

    end P;

    with Ada.Text_IO; use Ada.Text_IO;

    with P;           use P;

    procedure Show_Empty_Byte is
    begin
       Put_Line ("R'Size:        "
                 & R'Size'Image);
       Put_Line ("R'Object_Size: "
                 & R'Object_Size'Image);
    end Show_Empty_Byte;

If the code compiles, :ada:`R'Size` and :ada:`R'Object_Size` should now have
the same value.

Derived Types And Representation Clauses
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

In some cases, you might want to modify the memory representation of a record
without impacting existing code. For example, you might want to use a record
type that was declared in a package that you're not allowed to change. Also,
you would like to modify its memory representation in your application. A nice
strategy is to derive a type and use a representation clause for the derived
type.

We can apply this strategy on our previous example. Let's say we would like to
use record type :ada:`R` from package :ada:`P` in our application, but we're
not allowed to modify package :ada:`P` |mdash| or the record type, for that
matter. In this case, we could simply derive :ada:`R` as :ada:`R_New` and use a
representation clause for :ada:`R_New`. This is exactly what we do in the
specification of the child package :ada:`P.Rep`:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Record_Representation_Storage_Clauses.Derived_Rep_Clauses_Empty_Byte

    package P is

       type R is record
          A : Integer;
          B : Integer;
       end record;

    end P;

    package P.Rep is

       type R_New is new R
         with Object_Size => 72;

       for R_New use record
          A at 0 range 0 .. 31;
          B at 5 range 0 .. 31;
       end record;

    end P.Rep;

    with Ada.Text_IO; use Ada.Text_IO;

    with P;           use P;
    with P.Rep;       use P.Rep;

    procedure Show_Empty_Byte is
    begin
       Put_Line ("R'Size:        "
                 & R'Size'Image);
       Put_Line ("R'Object_Size: "
                 & R'Object_Size'Image);

       Put_Line ("R_New'Size:        "
                 & R_New'Size'Image);
       Put_Line ("R_New'Object_Size: "
                 & R_New'Object_Size'Image);
    end Show_Empty_Byte;

When running this example, we see that the :ada:`R` type retains the memory
representation selected by the compiler for the target architecture, while the
:ada:`R_New` has the memory representation that we specified.

Representation on Bit Level
~~~~~~~~~~~~~~~~~~~~~~~~~~~

A very common application of representation clauses is to specify individual
bits of a record. This is particularly useful, for example, when mapping
registers or implementing protocols.

Let's consider the following fictitious register as an example:

.. graphviz::

    digraph foo {
        "Record_R" [
            label = "{ bit | component } | { { 0 | 1 }  | S } | { { 2 | 3 } | (reserved) } | { 4 | Error } | { { 5 | 6 | 7 } | V1 }"
            shape = "record"
        ];
   }

Here, :ada:`S` is the current status, :ada:`Error` is a flag, and :ada:`V1`
contains a value. Due to the fact that we can use representation clauses to
describe individual bits of a register as records, the implementation becomes
as simple as this:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Record_Representation_Storage_Clauses.Rep_Clauses_Simple_Reg

    package P is

      type Status is (Ready, Waiting,
                      Processing, Done);
      type UInt_3 is range 0 .. 2 ** 3 - 1;

       type Simple_Reg is record
          S     : Status;
          Error : Boolean;
          V1    : UInt_3;
       end record;

       for Simple_Reg use record
          S     at 0 range 0 .. 1;
          --  Bit #2 and 3: reserved!
          Error at 0 range 4 .. 4;
          V1    at 0 range 5 .. 7;
       end record;

    end P;

    with Ada.Text_IO; use Ada.Text_IO;

    with P;           use P;

    procedure Show_Simple_Reg is
    begin
       Put_Line ("Simple_Reg'Size:        "
                 & Simple_Reg'Size'Image);
       Put_Line ("Simple_Reg'Object_Size: "
                 & Simple_Reg'Object_Size'Image);
    end Show_Simple_Reg;

As we can see in the declaration of the :ada:`Simple_Reg` type, each component
represents a field from our register, and it has a fixed location (which
matches the register representation we see in the graph above). Any operation
on the register is as simple as accessing the record component. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Record_Representation_Storage_Clauses.Rep_Clauses_Simple_Reg

    with Ada.Text_IO; use Ada.Text_IO;

    with P;           use P;

    procedure Show_Simple_Reg is
       Default : constant Simple_Reg :=
                   (S     => Ready,
                    Error => False,
                    V1    => 0);

       R : Simple_Reg := Default;
    begin
       Put_Line ("R.S:  " & R.S'Image);

       R.V1 := 4;

       Put_Line ("R.V1: " & R.V1'Image);
    end Show_Simple_Reg;

As we can see in the example, to retrieve the current status of the register,
we just have to write :ada:`R.S`. To update the *V1* field of the register with
the value 4, we just have to write :ada:`R.V1 := 4`. No extra code |mdash|
such as bit-masking or bit-shifting |mdash| is needed here.

.. admonition:: In other languages

    Some programming languages require that developers use complicated,
    error-prone approaches |mdash| which may include manually bit-shifting and
    bit-masking variables |mdash| to retrieve information from or store
    information to individual bits or registers. In Ada, however, this is
    efficiently handled by the compiler, so that developers only need to
    correctly describe the register mapping using representation clauses.


.. _Adv_Ada_Changing_Data_Representation:

Changing Data Representation
----------------------------

.. note::

    This section was originally written by Robert Dewar and published as
    `Gem #27: Changing Data Representation <https://www.adacore.com/gems/gem-27>`_
    and `Gem #28 <https://www.adacore.com/gems/gem-28>`_.

A powerful feature of Ada is the ability to specify the exact data layout. This
is particularly important when you have an external device or program that
requires a very specific format. Some examples are:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Changing_Data_Representation.Com_Packet

    package Communication is

       type Com_Packet is record
          Key : Boolean;
          Id  : Character;
          Val : Integer range 100 .. 227;
       end record;

       for Com_Packet use record
          Key at 0 range 0 .. 0;
          Id  at 0 range 1 .. 8;
          Val at 0 range 9 .. 15;
       end record;

    end Communication;

which lays out the fields of a record, and in the case of :ada:`Val`, forces a
biased representation in which all zero bits represents 100. Another example
is:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Changing_Data_Representation.Array_Rep

    package Array_Representation is

       type Val is (A, B, C, D, E, F, G, H);

       type Arr is array (1 .. 16) of Val
         with Component_Size => 3;

    end Array_Representation;

which forces the components to take only 3 bits, crossing byte boundaries as
needed. A final example is:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Changing_Data_Representation.Enum_Rep

    package Enumeration_Representation is

       type Status is (Off, On, Unknown);
       for Status use (Off     => 2#001#,
                       On      => 2#010#,
                       Unknown => 2#100#);

    end Enumeration_Representation;

which allows specified values for an enumeration type, instead of the efficient
default values of 0, 1, 2.

In all these cases, we might use these representation clauses to match external
specifications, which can be very useful. The disadvantage of such layouts is
that they are inefficient, and accessing individual components, or, in the case
of the enumeration type, looping through the values can increase space and
time requirements for the program code.

One approach that is often effective is to read or write the data in question
in this specified form, but internally in the program represent the data in the
normal default layout, allowing efficient access, and do all internal
computations with this more efficient form.

To follow this approach, you will need to convert between the efficient format
and the specified format. Ada provides a very convenient method for doing this,
as described in :arm22:`RM 13.6 "Change of Representation" <13-6>`.

The idea is to use type derivation, where one type has the specified format and
the other has the normal default format. For instance for the array case above,
we would write:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Changing_Data_Representation.Array_Rep

    package Array_Representation is

       type Val is (A, B, C, D, E, F, G, H);
       type Arr is array (1 .. 16) of Val;

       type External_Arr is new Arr
         with Component_Size => 3;

    end Array_Representation;

Now we read and write the data using the :ada:`External_Arr` type. When we want
to convert to the efficient form, :ada:`Arr`, we simply use a type conversion.

          procedure Display_State (S : State) is
          begin
             --  Before displaying the value,
             --  check whether it's valid or not.
             if S'Valid then
                Put_Line (S'Image);
             else
                Put_Line ("Invalid value detected!");
             end if;
          end Display_State;

       begin
          Open (F, In_File, File_Name);

          while not End_Of_File (F) loop
             Read (F, S);
             Display_State (S);
          end loop;

          Close (F);
       end Read_Display_States;

    end States;

    with States;           use States;
    with Create_Test_File;

    procedure Show_States_From_File is
       File_Name : constant String := "data.bin";
    begin
       Create_Test_File (File_Name);
       Read_Display_States (File_Name);
    end Show_States_From_File;

.. only:: builder_html

    When running the application, you'd see this output:

    ::

        OFF
        ON
        WAITING
        Invalid value detected!
        ON
        Invalid value detected!

Let's start our discussion on this example with the :ada:`States` package,
which contains the declaration of the :ada:`State` type. This type is a simple
enumeration containing three states: :ada:`Off`, :ada:`On` and :ada:`Waiting`.
We're assigning specific integer values for this type by declaring an
enumeration representation clause. Note that we're using the :ada:`Size` aspect
to request that objects of this type have the same size as the :ada:`Integer`
type. This becomes important later on when parsing data from the file.

In the :ada:`Create_Test_File` procedure, we create a file containing integer
values, which is parsed later by the :ada:`Read_Display_States` procedure. The
:ada:`Create_Test_File` procedure doesn't contain any reference to the
:ada:`State` type, so we're not constrained to just writing information that is
valid for this type. On the contrary, this procedure makes use of the
:ada:`Integer` type, so we can write any integer value to the file. We use this
strategy to write both valid and invalid values of :ada:`State` to the file.
This allows us to simulate an environment where transmission errors occur.

We call the :ada:`Read_Display_States` procedure to read information from the
file and display each state stored in the file. In the main loop of this
procedure, we call :ada:`Read` to read a state from the file and store it in
the :ada:`S` variable. We then call the nested :ada:`Display_State` procedure
to display the actual state stored in :ada:`S`. The most important line of code
in the :ada:`Display_State` procedure is the one that uses the :ada:`Valid`
attribute:

.. code-block:: ada

    if S'Valid then

In this line, we're verifying that the :ada:`S` variable contains a valid state
before displaying the actual information from :ada:`S`. If the value stored in
:ada:`S` isn't valid, we can handle the issue accordingly. In this case, we're
simply displaying a message indicating that an invalid value was detected. If
we didn't have this check, the :ada:`Constraint_Error` exception would be
raised when trying to use invalid data stored in :ada:`S` |mdash| this would
happen, for example, after reading the integer value 3 from the input file.

In summary, using the :ada:`Valid` attribute is a good strategy we can employ
when we know that information stored in memory might be corrupted.

.. admonition:: In the Ada Reference Manual

    - :arm22:`13.9.2 The Valid Attribute <13-9-2>`


.. _Adv_Ada_Unchecked_Union:

Unchecked Union
---------------

We've introduced variant records back in the
:ref:`Introduction to Ada course <Intro_Ada_Variant_Records>`.
In simple terms, a variant record is a record with discriminants that allows
for changing its structure. Basically, it's a record containing a :ada:`case`.
(We talk again about :ref:`variant records <Adv_Ada_Variant_Records>` in
another chapter.)

The :ada:`State_Or_Integer` declaration in the :ada:`States` package below is
an example of a variant record:

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.State_Or_Integer

    package States is

       type State is (Off, On, Waiting)
         with Size => Integer'Size;

       for State use (Off     => 1,
                      On      => 2,
                      Waiting => 4);

       type State_Or_Integer (Use_Enum : Boolean) is
       record
          case Use_Enum is
             when False => I : Integer;
             when True  => S : State;
          end case;
       end record;

       procedure Display_State_Value
         (V : State_Or_Integer);

    end States;

    with Ada.Text_IO; use Ada.Text_IO;

    package body States is

       procedure Display_State_Value
         (V : State_Or_Integer)
       is
       begin
          Put_Line ("State: " & V.S'Image);
          Put_Line ("Value: " & V.I'Image);
       end Display_State_Value;

    end States;

As mentioned in the previous course, if you try to access a component that is
not valid for your record, a :ada:`Constraint_Error` exception is raised. For
example, in the implementation of the :ada:`Display_State_Value` procedure,
we're trying to retrieve the value of the integer component (:ada:`I`) of the
:ada:`V` record. When calling this procedure, the :ada:`Constraint_Error`
exception is raised as expected because :ada:`Use_Enum` is set to :ada:`True`,
so that the :ada:`I` component is invalid |mdash| only the :ada:`S` component
is valid in this case.

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.State_Or_Integer
    :class: ada-run-expect-failure

    with States; use States;

    procedure Show_Variant_Rec_Error is
       V : State_Or_Integer (Use_Enum => True);
    begin
       V.S := On;
       Display_State_Value (V);
    end Show_Variant_Rec_Error;

In addition to not being able to read the value of a component that isn't
valid, assigning a value to a component that isn't valid also raises an
exception at runtime. In this example, we cannot assign to :ada:`V.I`:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.State_Or_Integer
    :class: ada-run-expect-failure

    with States; use States;

    procedure Show_Variant_Rec_Error is
       V : State_Or_Integer (Use_Enum => True);
    begin
       V.I := 4;
       --  Error: V.I cannot be accessed because
       --         Use_Enum is set to True.
    end Show_Variant_Rec_Error;

We may circumvent this limitation by using the :ada:`Unchecked_Union` aspect.
For example, we can derive a new type from :ada:`State_Or_Integer` and use
this aspect in its declaration. We do this in the declaration of the
:ada:`Unchecked_State_Or_Integer` type below.

.. code:: ada compile_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer

    package States is

       type State is (Off, On, Waiting)
         with Size => Integer'Size;

       for State use (Off     => 1,
                      On      => 2,
                      Waiting => 4);

       type State_Or_Integer (Use_Enum : Boolean) is
       record
          case Use_Enum is
             when False => I : Integer;
             when True  => S : State;
          end case;
       end record;

       type Unchecked_State_Or_Integer
         (Use_Enum : Boolean) is new
           State_Or_Integer (Use_Enum)
             with Unchecked_Union;

       procedure Display_State_Value
         (V : Unchecked_State_Or_Integer);

    end States;

    with Ada.Text_IO; use Ada.Text_IO;

    package body States is

       procedure Display_State_Value
         (V : Unchecked_State_Or_Integer)
       is
       begin
          Put_Line ("State: " & V.S'Image);
          Put_Line ("Value: " & V.I'Image);
       end Display_State_Value;

    end States;

Because we now use the :ada:`Unchecked_State_Or_Integer` type for the input
parameter of the :ada:`Display_State_Value` procedure, no exception is raised
at runtime, as both components are now accessible. For example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer

    with States; use States;

    procedure Show_Unchecked_Union is
       V : State_Or_Integer (Use_Enum => True);
    begin
       V.S := On;
       Display_State_Value
         (Unchecked_State_Or_Integer (V));
    end Show_Unchecked_Union;

Note that, in the call to the :ada:`Display_State_Value` procedure, we first
need to convert the :ada:`V` argument from the :ada:`State_Or_Integer` to the
:ada:`Unchecked_State_Or_Integer` type.

Also, we can assign to any of the components of a record that has the
:ada:`Unchecked_Union` aspect. In our example, we can now assign to both the
:ada:`S` and the :ada:`I` components of the :ada:`V` record:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer

    with States; use States;

    procedure Show_Unchecked_Union is
       V : Unchecked_State_Or_Integer
             (Use_Enum => True);
    begin
       V := (Use_Enum => True, S => On);
       Display_State_Value (V);

       V := (Use_Enum => False, I => 4);
       Display_State_Value (V);
    end Show_Unchecked_Union;

In the example above, we're using an aggregate in the assignments to :ada:`V`. By
doing so, we avoid that :ada:`Use_Enum` is set to the *wrong* component. For
example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer
    :class: ada-run-expect-failure

    with States; use States;

    procedure Show_Unchecked_Union is
       V : Unchecked_State_Or_Integer
             (Use_Enum => True);
    begin
       V.S := On;
       Display_State_Value (V);

       V.I := 4;
       --  Error: cannot directly assign to V.I,
       --         as Use_Enum is set to True.

       Display_State_Value (V);
    end Show_Unchecked_Union;

Here, even though the record has the :ada:`Unchecked_Union` attribute, we
cannot directly assign to the :ada:`I` component because :ada:`Use_Enum` is set
to :ada:`True`, so only the :ada:`S` is accessible. We can, however, read its
value, as we do in the :ada:`Display_State_Value` procedure.

Be aware that, due to the fact that the union is not checked, we might write invalid
data to the record. In the example below, we initialize the :ada:`I` component
with 3, which is a valid integer value, but results in an invalid value for
the :ada:`S` component, as the value 3 cannot be mapped to the representation
of the :ada:`State` type.

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer
    :class: ada-run-expect-failure

    with States; use States;

    procedure Show_Unchecked_Union is
       V : Unchecked_State_Or_Integer
             (Use_Enum => True);
    begin
       V := (Use_Enum => False, I => 3);
       Display_State_Value (V);
    end Show_Unchecked_Union;

To mitigate this problem, we could use the :ada:`Valid` attribute |mdash|
discussed in the previous section |mdash| for the :ada:`S` component before
trying to use its value in the implementation of the :ada:`Display_State_Value`
procedure:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Unchecked_Union.Unchecked_State_Or_Integer

    with Ada.Text_IO; use Ada.Text_IO;

    package body States is

       procedure Display_State_Value
         (V : Unchecked_State_Or_Integer)
       is
       begin
          if V.S'Valid then
             Put_Line ("State: " & V.S'Image);
          else
             Put_Line ("State: <invalid>");
          end if;
          Put_Line ("Value: " & V.I'Image);
       end Display_State_Value;

    end States;

    with States; use States;

          --
          --  Address arithmetic
          --
          A := A + Storage_Offset (Integer'Size)
                     / Storage_Unit;
          --     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
          --       Moving to next component
       end loop;

       for I in Arr'Range loop
         Put_Line ("Arr ("
                   & Integer'Image (I)
                   & ") :"
                   & Integer'Image (Arr (I)));
       end loop;
    end Show_Address;

In this example, we initialize the address :ada:`A` by retrieving the address
of the first component of the array :ada:`Arr`. (Note that we could have
written :ada:`Arr(1)'Address` instead of :ada:`Arr'Address`. In any
case, the language guarantees that :ada:`Arr'Address` gives us the address of
the first component, i.e. :ada:`Arr'Address = Arr(1)'Address`.)

Then, in the loop, we declare
an overlay :ada:`Curr` using the current value of the :ada:`A` address. We can
then operate on this overlay |mdash| here, we assign :ada:`I` to :ada:`Curr`.
Finally, in the loop, we increment address :ada:`A` and make it *point* to the
next component in the :ada:`Arr` array |mdash| to do so, we calculate the size
of an :ada:`Integer` component in storage units. (For details on storage units,
see the section on
:ref:`storage size attribute <Adv_Ada_Storage_Size_Attribute>`.)

.. admonition:: In other languages

    The code example above corresponds (more or less) to the following C code:

    .. code:: c manual_chop run_button main=main.c project=Courses.Advanced_Ada.Data_Types.Type_Representation.Addresses.Pointer_Arith_C

        !main.c
        #include <stdio.h>

        int main(int argc, const char * argv[])
        {
            int i;
            int arr[10];

            int *a = arr;
            /* int *a = &arr[0]; */

            for (i = 0; i < 10; i++)
            {
                *a++ = i;
                printf("curr address: %p\n", a);
            }

            for (i = 0; i < 10; i++)
            {
                printf("arr[%d]: %d\n", i, arr[i]);
            }

            return 0;
        }

    While pointer arithmetic is very common in C, using address arithmetic in
    Ada is far from common, and it should be only used when it's really
    necessary to do so.

.. admonition:: In the Ada Reference Manual

    - :arm22:`13.3 Operational and Representation Attributes <13-3>`
    - :arm22:`13.7.1 The Package System.Storage_Elements <13-7-1>`


Discarding names
----------------

As we know, we can use the :ada:`Image` attribute of a type to get a string
associated with this type. This is useful for example when we want to display a
user message for an enumeration type:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Discarding_Names.Enumeration_Image

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Enumeration_Image is

       type Months is
         (January, February, March, April,
          May, June, July, August, September,
          October, November, December);

       M : constant Months := January;
    begin
       Put_Line ("Month: "
                 & Months'Image (M));
    end Show_Enumeration_Image;

This is similar to having this code:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Discarding_Names.Enumeration_Image

    with Ada.Text_IO; use Ada.Text_IO;

    procedure Show_Enumeration_Image is

       type Months is
         (January, February, March, April,
          May, June, July, August, September,
          October, November, December);

       M : constant Months := January;

       function Months_Image (M : Months)
                              return String is
       begin
          case M is
             when January   => return "JANUARY";
             when February  => return "FEBRUARY";
             when March     => return "MARCH";
             when April     => return "APRIL";
             when May       => return "MAY";
             when June      => return "JUNE";
             when July      => return "JULY";
             when August    => return "AUGUST";
             when September => return "SEPTEMBER";
             when October   => return "OCTOBER";
             when November  => return "NOVEMBER";
             when December  => return "DECEMBER";
          end case;
       end Months_Image;

    begin
       Put_Line ("Month: "
                 & Months_Image (M));
    end Show_Enumeration_Image;

Here, the :ada:`Months_Image` function associates a string with each month of
the :ada:`Months` enumeration. As expected, the compiler needs to store the
strings used in the :ada:`Months_Image` function when compiling this code.
Similarly, the compiler needs to store strings for the :ada:`Months`
enumeration for the :ada:`Image` attribute.

Sometimes, we don't need to call the :ada:`Image` attribute for a type. In
this case, we could save some storage by eliminating the strings associated
with the type. Here, we can use the :ada:`Discard_Names` aspect to request the
compiler to reduce |mdash| as much as possible |mdash| the amount of storage
used for storing names for this type. Let's see an example:

.. code:: ada run_button project=Courses.Advanced_Ada.Data_Types.Type_Representation.Discarding_Names.Discard_Names

    procedure Show_Discard_Names is
       pragma Warnings (Off, "is not referenced");

       type Months is
         (January, February, March, April,
          May, June, July, August, September,
          October, November, December)
         with Discard_Names;

       M : constant Months := January;
    begin
       null;
    end Show_Discard_Names;

In this example, the compiler attempts to not store strings associated with
the :ada:`Months` type during compilation.

Note that the :ada:`Discard_Names` aspect is available for enumerations,
exceptions, and tagged types.

.. admonition:: In the GNAT toolchain

    If we add this statement to the :ada:`Show_Discard_Names` procedure above:

    .. code-block:: ada

        Put_Line ("Month: "
                  & Months'Image (M));

    we see that the application displays "0" instead of "JANUARY". This is
    because GNAT doesn't store the strings associated with the :ada:`Months`
    type when we use the :ada:`Discard_Names` aspect for the :ada:`Months`
    type. (Therefore, the :ada:`Months'Image` attribute doesn't have that
    information.) Instead, the compiler uses the integer value of the
    enumeration, so that :ada:`Months'Image` returns the corresponding string
    for this integer value.

.. admonition:: In the Ada Reference Manual

    - :arm22:`Aspect Discard_Names <C-5>`

Interfacing with C and C++
==========================

.. include:: ../../../../global.txt

Interfacing with C
------------------

Using unconstrained types
~~~~~~~~~~~~~~~~~~~~~~~~~

In the previous examples, we're being careful about the data types: all of
them are coming from the :ada:`Interfaces.C` package. Using Ada built-in
types when interfacing with C can be problematic, especially in case of
unconstrained types. For example:

.. code-block:: c

    /*% filename: test.h */

    char * my_func (void);

This is the function implementation:

.. code-block:: c

    #include <stdio.h>
    #include "test.h"

    char * my_func (void)
    {
      return "hello";
    }

In the Ada application, we try to import this as a :ada:`String` type:

.. code-block:: ada

    with Interfaces.C;
    use  Interfaces.C;

    with Ada.Text_IO;
    use  Ada.Text_IO;

    procedure Show_C_Func is

       function my_func return String
         with
           Import        => True,
           Convention    => C;

       S : String := my_func;

    begin
       Put_Line (S);
    end Show_C_Func;

When running this application, we'll get a :ada:`Storage_Error` exception.
Therefore, the recommendation is to be very careful about the data types
and use the :ada:`Interfaces.C` package whenever possible for interfacing
with C.

Interfacing with C++
--------------------

All the previous examples focused on interfacing with C code. For C++, the
same methods apply. However, there are a few differences that we need to
take into account:

- When importing or exporting variables and subprograms, we replace 'C'
  by 'Cpp' in the :ada:`Convention` aspect of their declaration.

- In the project file for :program:`gprbuild`, we replace 'C' by 'C++' in the
  ``Languages`` entry.

There are other aspects specific to C++ that we also have to take into
account. This section will discuss them.

C++ symbol mangling
~~~~~~~~~~~~~~~~~~~

Let's start by adapting a previous example and *converting* it to C++
(actually, mainly just replacing the C compiler by a C++ compiler). The
header file is still basically the same:

.. code-block:: c

    extern int func_cnt;
    int my_func (int a);

And this is the corresponding implementation:

.. code-block:: c

    #include "test.hh"

    int func_cnt = 0;

    int my_func (int a)
    {
      func_cnt++;

      return a * 2;
    }

In the Ada application, as mentioned before, we need to replace 'C' by
'Cpp' in the :ada:`Convention` of the declarations:

.. code-block:: ada

    with Interfaces.C; use Interfaces.C;
    with Ada.Text_IO;  use Ada.Text_IO;

    procedure Show_Cpp_Func is

       function my_func (a : int) return int
         with
           Import        => True,
           Convention    => Cpp,
           External_Name => "_Z7my_funci";

       V : int;

       func_cnt : int
         with
           Import        => True,
           Convention    => Cpp;

    begin
       V := my_func (1);
       V := my_func (2);
       V := my_func (3);
       Put_Line ("Result is "
                 & int'Image (V));

       Put_Line ("Function was called "
                 & int'Image (func_cnt)
                 & " times");

    end Show_Cpp_Func;

Also, in the declaration of :cpp:`my_func`, we need to include a reference to
the original name using :ada:`External_Name`. If we leave this out, the
linker won't be able to find the original implementation of :cpp:`my_func`,
so it won't build the application. Note that the function name is not
:cpp:`my_func` anymore (as was the case for the C version). Instead, it is
now called :cpp:`_Z7my_funci`.  This situation is caused by symbol mangling.

In C, the symbol names in object files match the symbol name in the
source-code. In C++, due to symbol mangling, the symbol names of
subprograms in the object files are different from the corresponding
source-code implementation. Also, because symbol mangling is not
standardized, different compilers might use different methods. The most
prominent example is the difference between the gcc and MSVC compilers.
However, since GNAT is based on gcc, we can build applications using Ada
and C++ code without issues |mdash| as long as we use the same compiler.

In order to retrieve the mangled symbol names, we can simply generate
bindings automatically by using :program:`g++` with the ``-fdump-ada-spec``
option:

.. code-block:: sh

    g++ -c -fdump-ada-spec -C ./test.hh

Alternatively, we could use binary examination tools to retrieve the
symbol names from a library. Examples of such tools are :program:`nm` for Mac and
Linux, and :program:`dumpbin.exe` for Windows.

C++ classes
~~~~~~~~~~~

We'll now focus on binding object-oriented features of C++ into Ada.
Let's adapt the previous example to make use of classes. This is adapted
header file:

.. code-block:: c

    class Test {
    public:
      Test();
      int my_func (int a);
      int get_cnt();
    private:
      int func_cnt;
    };

And this is the corresponding implementation:

.. code-block:: c

    #include "test.hh"

    Test::Test() :
      func_cnt(0)
    {
    };

    int
    Test::my_func (int a)
    {
      func_cnt++;

      return a * 2;
    }

    int
    Test::get_cnt()
    {
      return func_cnt;
    }

Because of the more complex structure, the recommendation is to generate
bindings using :program:`g++` and, if needed, adapt the file. Let's first run
:program:`g++`:

.. code-block:: sh

    g++ -c -fdump-ada-spec -C ./test.hh

The generated bindings look like this:

.. code-block:: ada

    pragma Ada_2005;
    pragma Style_Checks (Off);

    with Interfaces.C; use Interfaces.C;

    package test_hh is

       package Class_Test is
          type Test is limited record
             func_cnt : aliased int;  -- ./test.hh:7
          end record;
          pragma Import (CPP, Test);

          function New_Test return Test;  -- ./test.hh:3
          pragma CPP_Constructor (New_Test, "_ZN4TestC1Ev");

          function my_func (this : access Test; a : int) return int;  -- ./test.hh:4
          pragma Import (CPP, my_func, "_ZN4Test7my_funcEi");

          function get_cnt (this : access Test) return int;  -- ./test.hh:5
          pragma Import (CPP, get_cnt, "_ZN4Test7get_cntEv");
       end;
       use Class_Test;
    end test_hh;

As we can see, the original C++ class (:cpp:`Test`) is represented as a
nested package (:ada:`test_hh.Class_Test`) in the Ada bindings.

The Ada application can then use the bindings:

.. code-block:: ada

    with Interfaces.C; use Interfaces.C;
    with Ada.Text_IO;  use Ada.Text_IO;
    with test_hh;      use test_hh;

    procedure Show_Cpp_Class is
       use Class_Test;

       V : int;

       T  : aliased Test := New_Test;
       TA : access Test := T'Access;

    begin
       V := my_func (TA, 1);
       V := my_func (TA, 2);
       V := my_func (TA, 3);
       Put_Line ("Result is " & int'Image (V));

       Put_Line ("Function was called "
                 & int'Image (get_cnt (TA))
                 & " times");

    end Show_Cpp_Class;

Note that, in the Ada application, we cannot use the prefixed notation.
This notation would be more similar to the corresponding syntax in C++.
This restriction is caused by the fact that the automatically generated
bindings don't use tagged types. However, if we adapt the declaration of
:cpp:`Test` and replace it by :ada:`type Test is tagged limited record ...`,
we'll be able to write :ada:`TA.my_func(1)` and :ada:`TA.get_cnt` in our
application.

Another correction we might want to make is in the visibility of the
:ada:`Test` record. In the original C++ class, the :cpp:`func_cnt` element was
declared in the private part of the :cpp:`Test` class. However, in the
generated bindings, this element has been exposed, so it could be accessed
directly in our application. In order to correct that, we can simply move
the type declaration to the private part of the :ada:`Class_Test` package and
indicate that in the public part of the package (by using
:ada:`type Test is limited private;`).

After these adaptations, we get the following bindings:

.. code-block:: ada

    pragma Ada_2005;
    pragma Style_Checks (Off);

    with Interfaces.C; use Interfaces.C;

    package test_hh is

       package Class_Test is
          type Test is tagged limited private;
          pragma Import (CPP, Test);

          function New_Test return Test;  -- ./test.hh:3
          pragma CPP_Constructor (New_Test, "_ZN4TestC1Ev");

          function my_func (this : access Test; a : int) return int;  -- ./test.hh:4
          pragma Import (CPP, my_func, "_ZN4Test7my_funcEi");

          function get_cnt (this : access Test) return int;  -- ./test.hh:5
          pragma Import (CPP, get_cnt, "_ZN4Test7get_cntEv");
       private
          type Test is tagged limited record
             func_cnt : aliased int;  -- ./test.hh:7
          end record;
       end;
       use Class_Test;
    end test_hh;

And this is the adapted Ada application:

.. code-block:: ada

    with Interfaces.C; use Interfaces.C;
    with Ada.Text_IO;  use Ada.Text_IO;
    with test_hh;      use test_hh;

    procedure Show_Cpp_Class is
       use Class_Test;

       V : int;

       T : aliased Test := New_Test;
       TA : access Test := T'Access;

    begin
       V := TA.my_func (1);
       V := TA.my_func (2);
       V := TA.my_func (3);
       Put_Line ("Result is "
                 & int'Image (V));

       Put_Line ("Function was called "
                 & int'Image (TA.get_cnt)
                 & " times");

    end Show_Cpp_Class;


