             end loop;
          end Display;

          procedure Local_Init (A : in out My_Array) is
          begin
             A := (1, 2, 5, 10, -10);
          end Local_Init;

       begin
          case TC is
          when Init_Chk =>
             AA := Init (AA'First, AA'Length);
             AB := Init (AB'First, AB'Length);
             Display (AA);
             Display (AB);
          when Init_Proc_Chk =>
