	}
	log.Printf("Deleting Value %s from List %s", parts[2], parts[1])
	err := s.Beta().DeleteListValue(parts[1], parts[2])
	if err != nil {
		log.Printf("Error deleting Value %s to List %s: %s", parts[2], parts[1], err)
